functions.showPaymentScheduleModal:
function showPaymentScheduleModal(totalFeeValue, scheduleString, callback) {
  // ─── Amount parsing + formatting helpers ─────────────────────────────
  // Strip every non-numeric/dot/minus character before parseFloat so
  // formatted inputs like "$41,000.00" round-trip correctly.
  function _parseAmount(raw) {
    var s = String(raw == null ? "" : raw).replace(/[^0-9.\-]/g, "");
    var n = parseFloat(s);
    return isNaN(n) ? 0 : n;
  }
  // Format a number as "$XX,XXX.XX" (without the leading $ — caller
  // prepends currencySymbol). Always two decimals.
  function _formatMoney(n) {
    var v = Number(n) || 0;
    return v.toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  }

  var totalFee = _parseAmount(totalFeeValue);
  var formattedTotal = _formatMoney(totalFee);

  var overlay = document.createElement("div");
  overlay.className = "eli-overlay";
  overlay.style.gap = "18px";

  var card = document.createElement("div");
  card.className = "tool-box slide-in";
  // 2026-05-19 v8: resizable from bottom-right corner. `resize:both`
  // needs `overflow` other than `visible` to work — inner content area
  // has its own overflow-y:auto so the outer card uses `hidden`. min/
  // max constraints keep it within sane bounds. Not persisted: each
  // open starts at the default 420×auto.
  card.style.cssText =
    "background:#fff; width:380px; min-width:320px; max-width:95vw;" +
    " height:auto; min-height:240px; max-height:95vh;" +
    " padding:0; border-radius:0; box-shadow:0 24px 60px rgba(15,23,42,0.45);" +
    " border:1px solid #cbd5e1; display:flex; flex-direction:column;" +
    " resize:both; overflow:hidden;";
  // v6 build marker — visible in the header eyebrow so a stale-cache
  // diagnosis is one glance away. Update the version each time we ship
  // a visual change here so colleagues can confirm they're on it.
  // 2026-05-19 v9: tightened all font sizes + paddings + input heights
  // so more milestones fit before scrolling. Title 20→15, total 16→12,
  // labels stay 9px (already minimal), selects/inputs 14→11.5, input
  // height 48→34, paddings ~30-40% smaller. Action footer height also
  // dropped via tighter button padding.
  card.innerHTML =
    '<div style="background:linear-gradient(135deg,#0d1b2a 0%,#1b263b 100%); padding:10px 14px; border-bottom:2px solid #c9a227;">' +
      '<div style="font-size:8px; font-weight:800; color:#c9a227; text-transform:uppercase; letter-spacing:0.2em;">Auto-Fill Detected · v9 (compact)</div>' +
      '<div style="display:flex; justify-content:space-between; align-items:center; gap:10px; margin-top:3px;">' +
        '<div style="font-family:Georgia,serif; font-size:15px; font-weight:800; color:#fff; letter-spacing:-0.01em;">💰 Payment Schedule</div>' +
        '<div id="headerTotalDisplay" style="font-family:Georgia,serif; font-size:12px; font-weight:800; color:#fff; background:rgba(255,255,255,0.08); padding:3px 8px; border:1px solid rgba(201,162,39,0.5); font-variant-numeric:tabular-nums;">$' + formattedTotal + '</div>' +
      '</div>' +
    '</div>' +
    '<div style="padding:12px 14px; overflow-y:auto; flex:1; background:#f8fafc;">' +
      '<div style="margin-bottom:10px;">' +
        '<label style="display:block; font-size:8.5px; font-weight:800; color:#475569; text-transform:uppercase; letter-spacing:0.14em; margin-bottom:3px;">Currency</label>' +
        '<select id="payCurrency" style="width:100%; padding:6px 10px; font-size:11.5px; font-weight:600; color:#0f172a; background:#fff; border:1px solid #cbd5e1; border-radius:0; cursor:pointer; font-family:Inter,system-ui,sans-serif;">' +
          '<option value="USD" selected>USD ($)</option>' +
          '<option value="EUR">EUR (€)</option>' +
          '<option value="GBP">GBP (£)</option>' +
        '</select>' +
      '</div>' +
      '<div style="display:flex; gap:14px; margin-bottom:10px; padding-bottom:8px; border-bottom:1px solid #e2e8f0;">' +
        '<label style="font-size:10.5px; font-weight:700; color:#1e293b; display:flex; align-items:center; cursor:pointer;">' +
          '<input type="radio" name="payMode" value="percent" style="margin-right:5px; transform:scale(1.0);"> Percentage (%)' +
        '</label>' +
        '<label style="font-size:10.5px; font-weight:700; color:#1e293b; display:flex; align-items:center; cursor:pointer;">' +
          '<input type="radio" name="payMode" value="fixed" checked style="margin-right:5px; transform:scale(1.0);"> Fixed Amount ($)' +
        '</label>' +
      '</div>' +
      '<div id="payRowsContainer"></div>' +
      '<button id="btnAddPayRow" type="button" style="width:100%; margin-top:8px; padding:7px 12px; font-size:10px; font-weight:800; color:#1565c0; background:#fff; border:1px dashed #94a3b8; border-radius:0; cursor:pointer; text-transform:uppercase; letter-spacing:0.08em; font-family:Inter,system-ui,sans-serif; transition:background 0.12s ease, border-color 0.12s ease;" onmouseover="this.style.background=\'#eff6ff\';this.style.borderColor=\'#1565c0\';" onmouseout="this.style.background=\'#fff\';this.style.borderColor=\'#94a3b8\';">+ Add Payment Milestone</button>' +
      '<div id="payError" style="color:#b91c1c; font-size:10.5px; font-weight:700; margin-top:8px; display:none; text-align:center; background:#fef2f2; border:1px solid #fecaca; padding:6px;"></div>' +
      '<div id="payDateWarning" style="color:#9a3412; font-size:10.5px; font-weight:700; margin-top:6px; display:none; text-align:center; background:#fff7ed; padding:6px; border:1px solid #fed7aa;"></div>' +
    '</div>' +
    // ─── Premium action footer ─────────────────────────────────────────
    '<div style="padding:10px 14px; background:linear-gradient(180deg,#fff,#f8fafc); border-top:1px solid #e2e8f0; display:flex; gap:8px;">' +
      '<button id="btnPayCancel" type="button" style="flex:0 0 auto; padding:8px 16px; font-size:10.5px; font-weight:800; color:#475569; background:linear-gradient(180deg,#fff,#f1f5f9); border:1px solid #cbd5e1; border-radius:0; cursor:pointer; text-transform:uppercase; letter-spacing:0.1em; font-family:Inter,system-ui,sans-serif; box-shadow:0 1px 2px rgba(15,23,42,0.06), inset 0 1px 0 rgba(255,255,255,0.9); transition:transform 0.12s ease, box-shadow 0.12s ease;" onmouseover="this.style.boxShadow=\'0 2px 6px rgba(15,23,42,0.10), inset 0 1px 0 rgba(255,255,255,0.9)\';this.style.transform=\'translateY(-1px)\';" onmouseout="this.style.boxShadow=\'0 1px 2px rgba(15,23,42,0.06), inset 0 1px 0 rgba(255,255,255,0.9)\';this.style.transform=\'translateY(0)\';">Cancel</button>' +
      '<button id="btnPayApply" type="button" style="flex:1; padding:8px 16px; font-size:11px; font-weight:900; color:#fff; background:linear-gradient(180deg,#1565c0 0%,#0d47a1 100%); border:1px solid #0d47a1; border-bottom:2px solid #c9a227; border-radius:0; cursor:pointer; text-transform:uppercase; letter-spacing:0.12em; font-family:Inter,system-ui,sans-serif; box-shadow:0 3px 8px rgba(21,101,192,0.30), inset 0 1px 0 rgba(255,255,255,0.20); transition:transform 0.12s ease, box-shadow 0.12s ease;" onmouseover="this.style.boxShadow=\'0 5px 14px rgba(21,101,192,0.42), inset 0 1px 0 rgba(255,255,255,0.20)\';this.style.transform=\'translateY(-1px)\';" onmouseout="this.style.boxShadow=\'0 3px 8px rgba(21,101,192,0.30), inset 0 1px 0 rgba(255,255,255,0.20)\';this.style.transform=\'translateY(0)\';">✓ Apply Schedule</button>' +
    '</div>';

  overlay.appendChild(card);
  var showVerbatim = scheduleString && scheduleString.length > 5;
  if (showVerbatim) {
    var verbatimBox = document.createElement("div");
    verbatimBox.className = "tool-box slide-in";
    verbatimBox.style.cssText =
      "background:#fffde7; border:1px solid #fbc02d; width:240px; max-height:95vh; display:flex; flex-direction:column; border-radius:0; box-shadow:0 12px 30px rgba(15,23,42,0.25);";
    verbatimBox.innerHTML =
      '<div style="background:#fff9c4; padding:7px 10px; font-size:9.5px; font-weight:800; color:#92400e; border-bottom:1px solid #fbc02d; text-transform:uppercase; letter-spacing:0.12em;">🤖 AI Detected Text</div>' +
      '<div style="padding:10px 12px; font-size:11px; color:#5d4037; line-height:1.45; overflow-y:auto;">' + scheduleString + '</div>';
    overlay.appendChild(verbatimBox);
  }
  window._eliMountOverlay(overlay);
  var container = document.getElementById("payRowsContainer");
  var modeRadios = document.getElementsByName("payMode");
  var currentMode = "fixed";
  var currencySymbol = "$";
  var currencyCode = "USD";
  var currencyMap = { USD: "$", EUR: "€", GBP: "£" };

  function renderRow(prefillAmt, prefillType, prefillDate) {
    var div = document.createElement("div");
    div.className = "pay-row";
    div.style.cssText =
      "background:#fff; border:1px solid #e2e8f0; border-left:3px solid #cbd5e1; padding:8px 10px; margin-bottom:7px; position:relative;";
    // 2026-05-19 v2: amount input is now type=text so it can carry
    // formatted $XX,XXX.XX values (number-inputs reject commas). We
    // round-trip via _parseAmount/_formatMoney; inputmode=decimal
    // keeps mobile keyboards numeric. Trigger-value input gets
    // overflow:visible + no text-overflow:ellipsis + no maxlength
    // so long text isn't cut off.
    var amtPrefill = "";
    if (prefillAmt) {
      if (currentMode === "fixed") amtPrefill = _formatMoney(_parseAmount(prefillAmt));
      else amtPrefill = String(prefillAmt);
    }
    var triggerInputType = prefillType === "date" ? "date" : "text";
    var triggerPlaceholder = prefillType === "date"
      ? "" : (prefillType === "other" ? "Details…" : "e.g. Execution");
    var amountLabel = currentMode === "percent" ? "%" : currencySymbol;
    // 2026-05-19 v9: compact row — input height 48→34, fonts ~25% smaller,
    // tighter gaps + paddings + label margins. Each row drops from
    // ~120px tall to ~80px so 50% more rows fit before scrolling.
    div.innerHTML =
      '<div style="display:flex; gap:8px; margin-bottom:6px;">' +
        '<div style="flex:1; min-width:0;">' +
          '<label style="display:block; font-size:8.5px; font-weight:800; color:#64748b; text-transform:uppercase; letter-spacing:0.14em; margin-bottom:2px;">Amount (' + amountLabel + ')</label>' +
          '<input type="text" inputmode="decimal" class="pay-amount" placeholder="0" value="' + amtPrefill + '" style="width:100% !important; height:34px !important; min-height:34px !important; max-height:34px !important; padding:8px 10px !important; font-size:13px !important; font-weight:700 !important; line-height:1 !important; color:#0f172a !important; background:#fff !important; border:1px solid #cbd5e1 !important; border-radius:0 !important; font-family:Inter,system-ui,sans-serif !important; font-variant-numeric:tabular-nums !important; box-sizing:border-box !important; display:block !important;">' +
        '</div>' +
        '<div style="flex:1; min-width:0; display:flex; flex-direction:column; justify-content:flex-end;">' +
          '<div class="pay-calc" style="font-family:Georgia,serif; font-size:12px; font-weight:800; color:#b8961f; background:#fffbeb; padding:7px 10px; text-align:center; border:1px solid #fde68a; font-variant-numeric:tabular-nums; box-sizing:border-box;">' + currencySymbol + '0.00</div>' +
        '</div>' +
      '</div>' +
      '<div style="display:flex; gap:8px;">' +
        '<div style="flex:1; min-width:0;">' +
          '<select class="pay-trigger-type" style="width:100% !important; height:34px !important; min-height:34px !important; max-height:34px !important; padding:6px 10px !important; font-size:11.5px !important; font-weight:600 !important; color:#0f172a !important; background:#fff !important; border:1px solid #cbd5e1 !important; border-radius:0 !important; cursor:pointer; font-family:Inter,system-ui,sans-serif !important; box-sizing:border-box !important; display:block !important;">' +
            '<option value="event"' + (!prefillType || prefillType === "event" ? " selected" : "") + '>On Event</option>' +
            '<option value="date"' + (prefillType === "date" ? " selected" : "") + '>Specific Date</option>' +
            '<option value="other"' + (prefillType === "other" ? " selected" : "") + '>Other</option>' +
          '</select>' +
        '</div>' +
        '<div style="flex:1; min-width:0;">' +
          // 2026-05-19 v9: trigger input matches new compact height (34px).
          // overflow:visible + text-overflow:clip preserved so long event
          // descriptions still scroll horizontally instead of being cut off.
          '<input type="' + triggerInputType + '" class="pay-trigger-val" value="' + (prefillDate || "") + '" placeholder="' + triggerPlaceholder + '" style="width:100% !important; height:34px !important; min-height:34px !important; max-height:34px !important; padding:8px 10px !important; font-size:11.5px !important; font-weight:500 !important; line-height:1 !important; color:#0f172a !important; background:#fff !important; border:1px solid #cbd5e1 !important; border-radius:0 !important; font-family:Inter,system-ui,sans-serif !important; box-sizing:border-box !important; overflow:visible !important; text-overflow:clip !important; max-width:none !important; display:block !important;">' +
        '</div>' +
      '</div>' +
      '<div class="btn-del-row" title="Remove this milestone" style="position:absolute; top:-6px; right:-6px; background:linear-gradient(180deg,#ef4444,#b91c1c); color:#fff; width:16px; height:16px; font-size:9px; font-weight:800; display:flex; align-items:center; justify-content:center; cursor:pointer; box-shadow:0 2px 5px rgba(185,28,28,0.35); border:1px solid #7f1d1d;">✕</div>';
    var amountInput = div.querySelector(".pay-amount");
    var calcDisplay = div.querySelector(".pay-calc");
    var typeSel = div.querySelector(".pay-trigger-type");
    var valInput = div.querySelector(".pay-trigger-val");
    var delBtn = div.querySelector(".btn-del-row");
    function recomputeCalc() {
      var val = _parseAmount(amountInput.value);
      if (currentMode === "percent") {
        var calc = (val / 100) * totalFee;
        calcDisplay.innerText = currencySymbol + _formatMoney(calc);
      } else {
        var pct = totalFee > 0 ? (val / totalFee) * 100 : 0;
        calcDisplay.innerText = pct.toFixed(0) + "%";
      }
      validateTotal();
    }
    amountInput.oninput = recomputeCalc;
    // On blur: format as $XX,XXX.XX when in fixed mode. Strip back to
    // raw number on focus so editing is natural.
    amountInput.onblur = function () {
      if (currentMode === "fixed") {
        var n = _parseAmount(amountInput.value);
        amountInput.value = n > 0 ? _formatMoney(n) : "";
      }
    };
    amountInput.onfocus = function () {
      if (currentMode === "fixed") {
        var n = _parseAmount(amountInput.value);
        amountInput.value = n > 0 ? String(n) : "";
      }
    };
    typeSel.onchange = function () {
      if (this.value === "date") {
        valInput.type = "date";
        valInput.placeholder = "";
      } else {
        valInput.type = "text";
        valInput.placeholder = this.value === "event" ? "e.g. Execution" : "Details…";
      }
    };
    valInput.onchange = validateDates;
    delBtn.onclick = function () {
      if (container.children.length > 1) {
        div.remove();
        validateTotal();
      }
    };
    container.appendChild(div);
    if (prefillAmt) recomputeCalc();
  }

  function validateTotal() {
    var inputs = document.querySelectorAll(".pay-amount");
    var sum = 0;
    inputs.forEach(function (inp) { sum += _parseAmount(inp.value); });
    var err = document.getElementById("payError");
    var btn = document.getElementById("btnPayApply");
    var isValid = false;
    if (currentMode === "percent") {
      if (Math.abs(sum - 100) < 0.1) isValid = true;
      else err.innerText = "Total: " + sum + "% (must equal 100%)";
    } else {
      if (Math.abs(sum - totalFee) < 1.0) isValid = true;
      else err.innerText = "Total: " + currencySymbol + _formatMoney(sum) + " (must equal " + currencySymbol + _formatMoney(totalFee) + ")";
    }
    if (isValid) {
      err.style.display = "none";
      btn.style.opacity = "1";
      btn.disabled = false;
    } else {
      err.style.display = "block";
      btn.style.opacity = "0.5";
      btn.disabled = true;
    }
  }

  function validateDates() {
    var rows = container.querySelectorAll(".pay-row");
    var today = new Date();
    today.setHours(0, 0, 0, 0);
    var warnings = [];
    var lastDate = null;
    rows.forEach(function (row, index) {
      var type = row.querySelector(".pay-trigger-type").value;
      var val = row.querySelector(".pay-trigger-val").value;
      if (type === "date" && val) {
        var parts = val.split("-");
        var d = new Date(parts[0], parts[1] - 1, parts[2]);
        if (d < today) warnings.push("Row " + (index + 1) + ": date is in the past.");
        if (lastDate && d < lastDate) warnings.push("Row " + (index + 1) + ": date is out of order.");
        lastDate = d;
      }
    });
    var warnDiv = document.getElementById("payDateWarning");
    if (warnDiv) {
      if (warnings.length > 0) {
        warnDiv.innerHTML = "⚠️ " + warnings.join("<br>");
        warnDiv.style.display = "block";
      } else {
        warnDiv.style.display = "none";
      }
    }
  }

  document.getElementById("btnAddPayRow").onclick = function () { renderRow(); };
  document.getElementById("payCurrency").onchange = function () {
    currencyCode = this.value;
    currencySymbol = currencyMap[currencyCode] || "$";
    document.getElementById("headerTotalDisplay").innerText = currencySymbol + formattedTotal;
    container.innerHTML = "";
    renderRow();
    validateTotal();
  };
  Array.prototype.forEach.call(modeRadios, function (r) {
    r.onchange = function () {
      currentMode = this.value;
      container.innerHTML = "";
      renderRow();
      validateTotal();
    };
  });

  // ─── Parse AI-detected schedule, if any ──────────────────────────────
  // 2026-05-19 v3: split on milestone-BOUNDARY lookahead instead of on
  // every comma / "and". Pre-fix, text like:
  //   "50% upon delivery, acceptance, and signoff by both parties"
  // was split into 4 fragments by `,` and ` and `, dropping everything
  // after the first comma from the milestone's prose. Now we split
  // only at points that LOOK like a new milestone starts — a fresh
  // "<N>%" or "$<N>" token (optionally preceded by ";"). The prose
  // inside one milestone (commas, "and", etc.) is preserved verbatim.
  var hasSchedule = false;
  var scheduleTextForParsing = scheduleString || "";
  scheduleTextForParsing = scheduleTextForParsing
    .replace(/^(describe the payment schedule\/terms:|payment schedule:|payment terms:|fees:)\s*/i, "")
    .trim();
  if (scheduleTextForParsing.indexOf("%") !== -1 || /on\s|upon\s|due\s/i.test(scheduleTextForParsing)) {
    // Split BEFORE each new percentage or dollar amount — these mark
    // the start of a fresh milestone. Trailing `;` from the previous
    // milestone is trimmed below. Fallback: if no boundary is found,
    // the whole string is one milestone.
    var parts = scheduleTextForParsing.split(/(?=(?:^|[;\s])(?:\d+(?:\.\d+)?\s*%|\$\s*\d))/);
    parts = parts
      .map(function (p) { return String(p || "").replace(/^[;\s]+|[;\s]+$/g, ""); })
      .filter(function (p) { return p.length > 3; });
    var validRows = 0;
    // 2026-05-19: balanced-paren-aware trailing trimmer. Earlier
    // `.replace(/[);,.\s]+$/, "")` was greedy and stripped the closing
    // paren of legitimate phrases like "Execution (see Schedule A)" →
    // "Execution (see Schedule A". Now: strip ;,.\s always; strip a
    // trailing ')' only when the string has MORE closes than opens
    // (the outer-paren-wrapping case the original strip was meant for).
    function _trimMilestoneTail(s) {
      var out = String(s || "").trim().replace(/[;,.\s]+$/, "");
      while (/\)$/.test(out)) {
        var opens = (out.match(/\(/g) || []).length;
        var closes = (out.match(/\)/g) || []).length;
        if (closes <= opens) break;
        out = out.slice(0, -1).replace(/[;,.\s]+$/, "");
      }
      return out;
    }
    parts.forEach(function (part) {
      var amtMatch = part.match(/(\d+\.?\d*)\s*%/);
      var amt = amtMatch ? amtMatch[1] : "";
      // Grab everything from "on|upon|due" to end of part, INCLUDING
      // commas, "and", and parenthetical asides — all legitimate prose
      // inside a single milestone description.
      var dateMatch = part.match(/(?:on|upon|due)\s+(.+)/i);
      var dateVal = dateMatch ? _trimMilestoneTail(dateMatch[1]) : "";
      if (amt && dateVal) {
        if (validRows === 0 && scheduleTextForParsing.indexOf("%") !== -1) {
          currentMode = "percent";
          Array.prototype.forEach.call(modeRadios, function (r) { r.checked = r.value === "percent"; });
        }
        renderRow(amt, "event", dateVal);
        validRows++;
      }
    });
    if (validRows > 0) hasSchedule = true;
  }
  if (!hasSchedule) {
    if (totalFee > 0) {
      var defaultAmt = currentMode === "percent" ? "100" : totalFee;
      renderRow(defaultAmt);
    } else {
      renderRow();
    }
  } else {
    validateTotal();
  }

  document.getElementById("btnPayCancel").onclick = function () {
    overlay.remove();
    if (typeof callback === "function") callback(null);
  };
  document.getElementById("btnPayApply").onclick = function () {
    var rowElements = document.querySelectorAll(".pay-row");
    var parts = [];
    rowElements.forEach(function (row) {
      var amt = _parseAmount(row.querySelector(".pay-amount").value);
      var calc = row.querySelector(".pay-calc").innerText;
      var type = row.querySelector(".pay-trigger-type").value;
      var val = row.querySelector(".pay-trigger-val").value;
      var mainVal = "";
      var subVal = "";
      if (currentMode === "percent") {
        mainVal = amt + "%";
        subVal = "(" + calc + ")";
      } else {
        mainVal = currencySymbol + _formatMoney(amt);
        subVal = "";
      }
      var triggerText = val;
      if (type === "date" && val) {
        var dateParts = val.split("-");
        if (dateParts.length === 3) {
          var d = new Date(dateParts[0], dateParts[1] - 1, dateParts[2]);
          triggerText = "on " + d.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" });
        }
      }
      parts.push((mainVal + " " + subVal + " " + triggerText).replace(/\s+/g, " ").trim());
    });
    var finalStr = "due as follows: " + parts.join("; ") + ".";
    if (parts.length === 0) finalStr = "Payment schedule to be determined.";
    overlay.remove();
    callback(finalStr);
  };
}

engine.evalLogicCondition:
function evalLogicCondition(condStr, answers) {
  if (condStr === "true") return true;
  var op = condStr.indexOf("!=") !== -1 ? "!=" : "==";
  var parts = condStr.split(op);
  if (parts.length < 2) return false;
  var k = parts[0].trim();
  var rhs = parts[1].split("||").map(function (t) { return t.trim().replace(/['"]/g, ""); });
  var actual = answers && answers[k];
  if (actual === undefined) return false;
  return op === "==" ? rhs.indexOf(actual) !== -1 : rhs.indexOf(actual) === -1;
}

// Extract unique placeholders from text. Mirrors v2 runTemplateScan
// regex pair (line 6440) PLUS single-bracket marker forms used widely
// in ELI templates ($![Payment], $[Currency], ![Terms]). Pure unmarked
// [X] is intentionally NOT caught — that path is the bracket-cleaner
// for citations / cross-refs / author tags.

engine.extractTemplatePlaceholders:
function extractTemplatePlaceholders(text) {
  var src = String(text || "");
  var found = {};
  // Double brackets with optional $!/$/! prefix.
  var doubleBracketRe = /(\$!|\$|!)?\[\[(.*?)\]\]/g, dm;
  while ((dm = doubleBracketRe.exec(src))) if (dm[0].length > 2) found[dm[0]] = true;
  // Curly braces (template-fill markers, post-Step-1).
  var curlyRe = /\{\{([^}]+)\}\}(\*)?/g, cm;
  while ((cm = curlyRe.exec(src))) if (cm[0].length > 4) found[cm[0]] = true;
  // Single brackets WITH explicit $!/$/! prefix — unambiguous fill markers.
  // Inner allows letters/digits/spaces/punctuation; cap at 80 chars to
  // avoid catching whole sentences when authors forget to close a bracket.
  var singleBracketRe = /(\$!|\$|!)\[([^\[\]\n]{1,80})\]/g, sm;
  while ((sm = singleBracketRe.exec(src))) found[sm[0]] = true;
  return Object.keys(found);
}

engine.analyze:
async function analyze(input, providers) {
  function _esc(s) { return String(s == null ? "" : s); }

  // Load persisted state from Office settings (set by v2 persistAgreementState).
  function _readPersistedAgreement() {
    try {
      var s = (Office && Office.context && Office.context.document && Office.context.document.settings);
      if (!s) return null;
      var name = s.get("AgreementDataName");
      var type = s.get("AgreementDataType");
      var details = s.get("AgreementDataDetails");
      if (!name && !type && !details) return null;
      return {
        name: name || null,
        type: type || null,
        details: typeof details === "object" ? details : null,
      };
    } catch (e) {
      if (window.eli && window.eli.log) {
        window.eli.log.event("tool", "build_draft_persist_read_failed", { msg: e && e.message });
      }
      return null;
    }
  }

  // First-instance scan for whole-word OARS anywhere in body
  // (case-insensitive). Matches kernel's _eliCheckOarsAndLaunch.
  function _hasOarsAnywhere(bodyText) {
    if (!bodyText) return false;
    return /\bOARS\b/i.test(String(bodyText));
  }

  // Best-effort agreement-type extraction from OARS-formatted body text.
  // OARS docs have "Agreement Type: <type>" lines near the top.
  function _extractAgreementType(bodyText) {
    if (!bodyText) return null;
    var m = String(bodyText).match(/Agreement\s+Type\s*[:=]\s*([^\n\r]+)/i);
    return m ? m[1].trim() : null;
  }

  // Extract key/value pairs. Anchors on first OARS line if present,
  // otherwise parses the whole text. "Field: value" or "Field = value".
  function _extractFields(bodyText) {
    if (!bodyText) return {};
    var lines = String(bodyText).split(/\r?\n/);
    var startIdx = 0;
    for (var j = 0; j < lines.length; j++) {
      if (/\bOARS\b/i.test(lines[j])) { startIdx = j; break; }
    }
    var fields = {};
    var stop = false;
    for (var i = startIdx; i < lines.length && !stop; i++) {
      var ln = lines[i].trim();
      if (!ln) {
        if (Object.keys(fields).length) stop = true;
        continue;
      }
      var m = ln.match(/^([A-Za-z][A-Za-z0-9 _\-]+?)\s*[:=]\s*(.+)$/);
      if (m) fields[m[1].trim()] = m[2].trim();
    }
    return fields;
  }

  // Three OARS data sources (priority order):
  //   1. footerFile — manually uploaded via kernel's DATA loader
  //   2. doc body — auto-scanned
  //   3. doc headers — fallback
  // Highest-priority source with OARS marker wins. Sources are
  // concatenated for fallback field extraction.
  var bodyText   = (input && input.bodyText) || "";
  var headerText = (input && input.headerText) || "";
  var footerText = (input && input.footerFile && input.footerFile.text) || "";
  var footerName = (input && input.footerFile && input.footerFile.name) || null;

  var sourceText = "";
  var source = "none";
  if (_hasOarsAnywhere(footerText))      { sourceText = footerText; source = "footer_file"; }
  else if (_hasOarsAnywhere(bodyText))   { sourceText = bodyText;   source = "doc_body"; }
  else if (_hasOarsAnywhere(headerText)) { sourceText = headerText; source = "doc_header"; }
  else if (footerText)                   { sourceText = footerText; source = "footer_file_no_marker"; }

  var hasOars = source !== "none" && source !== "footer_file_no_marker";
  var persisted = _readPersistedAgreement();
  var detectedType = (persisted && persisted.type) || _extractAgreementType(sourceText);
  var fields = sourceText ? _extractFields(sourceText) : {};

  var releasedAt = "unknown";
  try {
    if (typeof window !== "undefined" && window.eli && window.eli.tools && window.eli.tools._loaded
        && window.eli.tools._loaded["build_draft"]) {
      releasedAt = window.eli.tools._loaded["build_draft"].releasedAt || "unknown";
    }
  } catch (e) {
    if (window.eli && window.eli.log) {
      window.eli.log.event("tool", "build_draft_releasedat_lookup_failed", { msg: e && e.message });
    }
  }

  // FROM v2 runDocumentScannerBuild (line 21358) — count {{...}} markers.
  // Read-only; the actual logic builder runs as wizard step 1.
  function _scanLogicMarkers(text) {
    var counts = { IF: 0, ELSEIF: 0, ELSE: 0, ENDIF: 0, DEF: 0, TITLE: 0, DELETE_LINE: 0, ENTER: 0, otherCurly: 0 };
    var defKeys = [];
    var re = /\{\{([^{}]+)\}\}/g, m;
    while ((m = re.exec(String(text || "")))) {
      var t = m[1].trim();
      if (t.indexOf("IF:") === 0) counts.IF++;
      else if (t.indexOf("ELSEIF:") === 0) counts.ELSEIF++;
      else if (t.indexOf("ELSE") === 0) counts.ELSE++;
      else if (t.indexOf("ENDIF") === 0) counts.ENDIF++;
      else if (t.indexOf("DEF:") === 0) {
        counts.DEF++;
        var kv = t.substring(4).split("|")[0].split("=")[0].trim();
        if (kv) defKeys.push(kv);
      }
      else if (t.indexOf("TITLE:") === 0) counts.TITLE++;
      else if (t === "DELETE_LINE") counts.DELETE_LINE++;
      else if (t === "ENTER") counts.ENTER++;
      else counts.otherCurly++;
    }
    var total = 0;
    for (var k in counts) total += counts[k];
    return { counts: counts, total: total, defKeys: defKeys };
  }

  // [Placeholder text] — square brackets used as fill targets (FROM v2
  // showBracketCleaner line 22706). Skips obvious false-positives like
  // citation refs ([1], [Author]).
  function _scanBrackets(text) {
    var src = String(text || "");
    var matches = [];
    var re = /\[([^\[\]\n]{2,80})\]/g, m;
    while ((m = re.exec(src))) {
      var inner = m[1].trim();
      // Skip pure-numeric refs ([1], [42]), single-word author cites,
      // and Word's tracked-change markers.
      if (/^\d+$/.test(inner)) continue;
      if (/^\[Comment[ \d]/i.test(m[0])) continue;
      matches.push({ text: m[0], inner: inner, index: m.index });
    }
    return { items: matches.slice(0, 50), total: matches.length };
  }

  // $ amounts in body — financial review trigger.
  function _scanFinancial(text) {
    var src = String(text || "");
    var matches = [];
    var re = /\$\s*[\d,]+(?:\.\d+)?/g, m;
    while ((m = re.exec(src))) {
      matches.push({ text: m[0].replace(/\s+/g, ""), index: m.index });
    }
    return { items: matches.slice(0, 50), total: matches.length };
  }

  // Full DEF parser — mirrors v2 parseLogicDefinition (line 21405).
  // Walks {{IF/ELSEIF/ELSE/ENDIF}} stack and records {{DEF:k=default|opts|warning}}
  // entries with their parent IF expressions as visibility dependencies.
  function _parseLogicDefs(text) {
    var src = String(text || "");
    var defs = {};
    var deps = {};
    var stack = [];
    var title = null;
    var titleMatch = src.match(/\{\{TITLE:\s*([^{}]+)\}\}/i);
    if (titleMatch) title = titleMatch[1].trim();
    var re = /\{\{([^{}]+)\}\}/g, m;
    while ((m = re.exec(src))) {
      var t = m[1].trim();
      if (t.indexOf("IF:") === 0) stack.push(t.substring(3).trim());
      else if (t.indexOf("ELSEIF:") === 0) {
        if (stack.length) { stack.pop(); stack.push(t.substring(7).trim()); }
      }
      else if (t.indexOf("ELSE") === 0) {
        if (stack.length) { stack.pop(); stack.push("true"); }
      }
      else if (t.indexOf("ENDIF") === 0) {
        if (stack.length) stack.pop();
      }
      else if (t.indexOf("DEF:") === 0 && t.indexOf("|") !== -1) {
        // 2026-05-21 v2: DEF format —
        //   {{DEF: key = default | options | extra1 | extra2 | …}}
        //              pipe[0]    pipe[1]   pipe[2+]
        //
        //   pipe[0]: "key = default" (default is optional)
        //   pipe[1]: comma-separated choices, OR "*placeholder" for text
        //   pipe[2..N]: any number of EXTRA segments. Each one is
        //               classified by its prefix:
        //
        //     "oars:Counterparty Name" → OARS lookup term. Triggers the
        //                                🔎 OARS LOOKUP button on the
        //                                question. Case-insensitive
        //                                search inside the OARS viewer.
        //     anything else            → warning / admin guidance, shown
        //                                inline below the label with a
        //                                ⚠️ icon. Preserves backward-
        //                                compatibility with existing
        //                                templates that put warnings in
        //                                pipe[2].
        //
        //   Order-independent. Either or both can be present. If you
        //   want both: `{{DEF: x = | a, b | warning text | oars:Field}}`
        //   or the reverse order — parser sorts by prefix.
        var clean = t.substring(4).trim();
        var pipe = clean.split("|");
        var defPart = pipe[0].trim();
        var optionsPart = pipe.length > 1 ? pipe[1].trim() : null;
        var oarsLookup = null;
        var warning = null;
        var guidance = null;
        for (var pi = 2; pi < pipe.length; pi++) {
          var seg = String(pipe[pi] || "").trim();
          if (!seg) continue;
          if (/^oars\s*:/i.test(seg)) {
            // Strip the "oars:" prefix; the remainder is the search term.
            if (!oarsLookup) oarsLookup = seg.replace(/^oars\s*:\s*/i, "").trim() || null;
          } else if (/^guidance\s*:/i.test(seg)) {
            // 2026-05-21: "guidance:" prefix opens a premium dialog
            // showing the body text. For longer instructional content
            // that doesn't fit as an inline warning chip.
            if (!guidance) guidance = seg.replace(/^guidance\s*:\s*/i, "").trim() || null;
          } else {
            if (!warning) warning = seg;
          }
        }
        if (!optionsPart) continue;
        var defSplit = defPart.split("=");
        var key = defSplit[0].trim();
        var explicitDefault = defSplit.length > 1 ? defSplit[1].trim() : "";
        var isText = optionsPart.charAt(0) === "*";
        var textDefault = isText ? optionsPart.substring(1).trim() : "";
        defs[key] = {
          default: explicitDefault || textDefault,
          isText: isText,
          options: isText ? [] : optionsPart.split(",").map(function (o) { return o.trim(); }),
          oarsLookup: oarsLookup,
          guidance: guidance,
          warning: warning,
        };
        if (stack.length > 0) deps[key] = stack.slice();
      }
    }
    return { defs: defs, deps: deps, count: Object.keys(defs).length, title: title };
  }

  var logicScan = _scanLogicMarkers(bodyText);
  var bracketScan = _scanBrackets(bodyText);
  var financialScan = _scanFinancial(bodyText);
  var logicDefs = _parseLogicDefs(bodyText);
  // Fill-candidate count: what Step 2 will actually offer to fill. Same
  // regex set as the top-level extractTemplatePlaceholders fn (inlined
  // because each engine fn is eval'd in its own scope and can't call
  // siblings directly). Body-only — Step 2's own scan extends to
  // headers + footers, so this can undercount slightly.
  function _scanFillCandidates(text) {
    var src = String(text || "");
    var found = {};
    var dRe = /(\$!|\$|!)?\[\[(.*?)\]\]/g, dm;
    while ((dm = dRe.exec(src))) if (dm[0].length > 2) found[dm[0]] = true;
    var cRe = /\{\{([^}]+)\}\}(\*)?/g, cm;
    while ((cm = cRe.exec(src))) if (cm[0].length > 4) found[cm[0]] = true;
    var sRe = /(\$!|\$|!)\[([^\[\]\n]{1,80})\]/g, sm;
    while ((sm = sRe.exec(src))) found[sm[0]] = true;
    return Object.keys(found);
  }
  var fillCandidates = _scanFillCandidates(bodyText);

  var sourceLabel = source === "footer_file" ? ("File: " + (footerName || "uploaded"))
                  : source === "footer_file_no_marker" ? ("File: " + (footerName || "uploaded"))
                  : source === "doc_body"   ? "Document body"
                  : source === "doc_header" ? "Document header"
                  : null;
  return {
    items: [],
    overview: hasOars
      ? ("OARS · " + (sourceLabel || "detected") + (detectedType ? " · " + detectedType : ""))
      : (footerText ? ("File loaded · " + (footerName || "—"))
        : persisted ? ("Saved · " + (persisted.type || persisted.name || "—")) : "Standard mode"),
    hasOars: hasOars,
    source: source,
    sourceLabel: sourceLabel,
    footerFile: input && input.footerFile ? { name: footerName, size: input.footerFile.size } : null,
    persisted: persisted,
    detectedType: detectedType,
    fieldCount: Object.keys(fields).length,
    fields: fields,
    logicScan: logicScan,
    bracketScan: bracketScan,
    financialScan: financialScan,
    fillScan: { items: fillCandidates, total: fillCandidates.length },
    logicDefs: logicDefs,
    provenance: {
      kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: releasedAt,
      docHash: null,
      timestamp: Date.now(),
    },
  };
}

view.renderHub:
function renderHub(opts) {
  var result = opts.result || {};
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var onClose = opts.onClose || function () {};
  var onRunAll = opts.onRunAll || function () {};
  var onTemplates = opts.onTemplates || function () {};
  var onStep = opts.onStep || function () {};
  var onClearOars = opts.onClearOars || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root";

  // Header bar — dark navy banner with gold accent rule (matches the
  // standard tool-hub header style). Right side carries a small
  // 📂 Templates button (replaces the old big TEMPLATES tile).
  var bar = document.createElement("div");
  bar.className = "_eli3_bd_bar";
  bar.innerHTML =
    '<button class="_eli3_bd_back" title="Back">←</button>' +
    '<div class="_eli3_bd_title">⚡ Build Draft Hub</div>' +
    '<button class="_eli3_bd_bar_templates" title="Templates library">📂</button>';
  bar.querySelector("._eli3_bd_back").onclick = onClose;
  bar.querySelector("._eli3_bd_bar_templates").onclick = onTemplates;
  root.appendChild(bar);

  // OARS status banner — shown when ANY source has data: OARS-marked
  // body/header, persisted state, or a footer-uploaded file.
  if (result.hasOars || result.persisted || result.footerFile) {
    var banner = document.createElement("div");
    banner.className = "_eli3_bd_oars_banner";
    var typeLabel = (result.detectedType || (result.persisted && result.persisted.type) || "—");
    var nameLabel = (result.persisted && result.persisted.name)
                  || (result.footerFile && result.footerFile.name)
                  || (result.hasOars ? "OARS document" : "");
    var sourceLine = result.sourceLabel
      ? '<div class="_eli3_bd_oars_source">' + _esc(result.sourceLabel) + '</div>'
      : '';
    banner.innerHTML =
      '<div class="_eli3_bd_oars_icon">📋</div>' +
      '<div class="_eli3_bd_oars_main">' +
        '<div class="_eli3_bd_oars_label">OARS DATA</div>' +
        '<div class="_eli3_bd_oars_value">' + _esc(typeLabel) + (nameLabel ? ' · ' + _esc(nameLabel) : '') + '</div>' +
        sourceLine +
        (result.fieldCount ? '<div class="_eli3_bd_oars_meta">' + result.fieldCount + ' field' + (result.fieldCount === 1 ? "" : "s") + ' parsed</div>' : '') +
      '</div>' +
      '<button class="_eli3_bd_oars_clear" title="Clear OARS data">✕</button>';
    banner.querySelector("._eli3_bd_oars_clear").onclick = onClearOars;
    root.appendChild(banner);
  }

  // Per-step list. Mirrors v2 renderAutoFillHubUI (line 21254): 4 steps,
  // Logic → Fill → Error Review → Save. Counts pulled from engine scans
  // for at-a-glance signal.
  var lc = (result.logicScan && result.logicScan.counts) || {};
  var logicTotal = (result.logicScan && result.logicScan.total) || 0;
  // fillScan.total is what Step 2 will actually offer (matches the regex
  // used by extractTemplatePlaceholders). bracketScan / financialScan
  // are broader — used by the bracket-cleaner step that runs after fill.
  var fillTotal = (result.fillScan && result.fillScan.total) || 0;
  var steps = [
    { n: 1, icon: "🏗️", label: "Build Logic", desc: logicTotal
        ? (logicTotal + " marker" + (logicTotal === 1 ? "" : "s") + " (" +
           (lc.IF || 0) + " IF · " + (lc.DEF || 0) + " DEF · " + (lc.TITLE || 0) + " TITLE)")
        : "Generate custom draft from {{IF}} logic.", id: "logic", count: logicTotal },
    { n: 2, icon: "✍️", label: "Fill Fields", desc: fillTotal
        ? (fillTotal + " placeholder" + (fillTotal === 1 ? "" : "s") + " to fill")
        : "Populate [[Brackets]] / {{Curlies}} / $![Markers].", id: "templates", count: fillTotal },
    { n: 3, icon: "📝", label: "Error Review", desc: "Full grammar & proofreading scan.", id: "error_review", count: 0 },
    { n: 4, icon: "💾", label: "Save and/or Send", desc: "Save the .docx and draft a Gmail email to the requester.", id: "save", count: 0 },
  ];
  // Step state — init.js tracks per-session completion in _bdCompleted
  // and passes it through opts.completedSteps. Completed steps show ✓
  // and dim; "current" is the first incomplete step.
  var completed = opts.completedSteps || {};
  var currentStep = 1;
  for (var si = 0; si < steps.length; si++) {
    if (!completed[steps[si].id]) { currentStep = steps[si].n; break; }
    if (si === steps.length - 1) currentStep = steps.length; // all done → highlight last
  }
  var list = document.createElement("div");
  list.className = "_eli3_bd_steps";
  steps.forEach(function (s) {
    var row = document.createElement("button");
    row.className = "_eli3_bd_step";
    var isDone = !!completed[s.id];
    var isCurrent = !isDone && s.n === currentStep;
    if (isCurrent) row.classList.add("_eli3_bd_step_current");
    if (isDone) row.classList.add("_eli3_bd_step_done");
    var badge = s.count ? '<span class="_eli3_bd_step_badge">' + s.count + '</span>' : '';
    var currentDot = isCurrent
      ? '<span class="_eli3_bd_step_dot" title="You are here"></span>'
      : '';
    var stepNumHtml = isDone
      ? '<span class="_eli3_bd_step_check" title="Completed">✓</span>'
      : (s.n + currentDot);
    row.innerHTML =
      '<span class="_eli3_bd_step_n">' + stepNumHtml + '</span>' +
      '<span class="_eli3_bd_step_icon">' + s.icon + '</span>' +
      '<span class="_eli3_bd_step_info">' +
        '<span class="_eli3_bd_step_label">' + _esc(s.label) + badge + '</span>' +
        '<span class="_eli3_bd_step_desc">' + _esc(s.desc) + '</span>' +
      '</span>' +
      '<span class="_eli3_bd_step_arrow">→</span>';
    row.onclick = function () { onStep(s.id, s); };
    list.appendChild(row);
  });
  root.appendChild(list);

  mount.appendChild(root);
}

// renderLogicForm — Step 1 v3-native port of v2 renderLogicBuilderForm
// (line 21428). Reads engine result.logicDefs (defs + deps) and renders
// a fill-in form with visibility tracking. onGenerate(answers) runs the
// Word.run replacement pipeline in init.js.

view.renderLogicForm:
function renderLogicForm(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var defs = opts.defs || {};
  var deps = opts.deps || {};
  var docTitle = opts.title || "Document Builder";
  var onGenerate = opts.onGenerate || function () {};
  var onBack = opts.onBack || function () {};
  var onScanForOars = opts.onScanForOars || function () {};
  var onOarsLookup = opts.onOarsLookup || function () {};
  var onGuidance = opts.onGuidance || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_logic";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">🏗️ ' + _esc(docTitle) + '</div>' +
      '<div class="_eli3_bd_overview">LOGIC ENGINE</div>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;

  var keys = Object.keys(defs);
  if (!keys.length) {
    var empty = document.createElement("div");
    empty.className = "_eli3_bd_logic_empty";
    empty.innerHTML =
      '<div class="_eli3_bd_logic_empty_icon">📄</div>' +
      '<div class="_eli3_bd_logic_empty_title">NO LOGIC TAGS FOUND</div>' +
      '<div class="_eli3_bd_logic_empty_desc">' +
        'This document does not contain ELI template logic.<br>' +
        'Open a template with <code>{{DEF:...}}</code> and <code>{{IF:...}}</code> tags.' +
      '</div>' +
      '<button class="_eli3_bd_run_all _eli3_bd_logic_oars_btn">SCAN FOR OARS DATA</button>';
    root.appendChild(empty);
    empty.querySelector("._eli3_bd_logic_oars_btn").onclick = onScanForOars;
    mount.appendChild(root);
    return;
  }

  var form = document.createElement("div");
  form.className = "_eli3_bd_logic_form";

  function _renderInputs() {
    form.innerHTML = "";
    keys.forEach(function (key) {
      var def = defs[key];
      var group = document.createElement("div");
      group.className = "_eli3_bd_logic_group";
      group.setAttribute("data-key", key);
      // 2026-05-21: label gains inline action buttons when the DEF
      // tag's extra pipe segments supplied them:
      //   • `| oars:<term>`     → 🔎 OARS LOOKUP   (opens OARS viewer)
      //   • `| guidance:<text>` → 📘 GUIDANCE      (opens premium dialog)
      //   • `| <other text>`    → ⚠️ inline warning chip (existing)
      var oarsBtnHtml = def.oarsLookup
        ? '<button type="button" class="_eli3_bd_logic_oars_lookup" data-oars-term="' + _esc(def.oarsLookup) + '" title="Open OARS viewer + jump to: ' + _esc(def.oarsLookup) + '">🔎 OARS LOOKUP</button>'
        : "";
      var guidanceBtnHtml = def.guidance
        ? '<button type="button" class="_eli3_bd_logic_guidance" title="Show guidance for this question">📘 GUIDANCE</button>'
        : "";
      var labelHtml = '<span class="_eli3_bd_logic_label_text">' + _esc(key) + '</span>' + guidanceBtnHtml + oarsBtnHtml +
        (def.warning ? '<span class="_eli3_bd_logic_warning">⚠️ ' + _esc(def.warning) + '</span>' : '');
      group.innerHTML = '<label class="_eli3_bd_logic_label">' + labelHtml + '</label>';
      if (def.isText) {
        var hint = document.createElement("div");
        hint.className = "_eli3_bd_logic_hint";
        hint.textContent = "Free Form Entry — leave as 'Don't know' if not sure.";
        group.appendChild(hint);
        // 2026-05-20: wrap text inputs in a leading-icon container so
        // free-text questions are visually distinct from dropdowns.
        // The icon + cream-amber tint signal "type here" vs "pick one"
        // at a glance, while preserving the gold-rail premium look.
        var wrap = document.createElement("div");
        wrap.className = "_eli3_bd_logic_text_wrap";
        var icon = document.createElement("span");
        icon.className = "_eli3_bd_logic_text_icon";
        icon.textContent = "✍️";
        icon.setAttribute("aria-hidden", "true");
        wrap.appendChild(icon);
        var inp = document.createElement("input");
        inp.type = "text";
        inp.className = "_eli3_bd_logic_input _eli3_bd_logic_input_text";
        inp.value = def.default || "";
        inp.placeholder = "Type your answer…";
        inp.setAttribute("data-key", key);
        inp.oninput = _updateVisibility;
        wrap.appendChild(inp);
        group.appendChild(wrap);
      } else {
        var sel = document.createElement("select");
        sel.className = "_eli3_bd_logic_input";
        sel.setAttribute("data-key", key);
        def.options.forEach(function (opt) {
          var o = document.createElement("option");
          o.value = opt; o.textContent = opt;
          if (opt === def.default) o.selected = true;
          sel.appendChild(o);
        });
        sel.onchange = _updateVisibility;
        group.appendChild(sel);
      }
      // Wire the OARS lookup button (only present when def.oarsLookup
      // was set). Stop propagation so clicking inside the <label>
      // doesn't toggle the underlying input/select.
      var oarsLookupBtn = group.querySelector("._eli3_bd_logic_oars_lookup");
      if (oarsLookupBtn) {
        oarsLookupBtn.onclick = function (ev) {
          ev.preventDefault();
          ev.stopPropagation();
          onOarsLookup(def.oarsLookup, key);
        };
      }
      var guidanceBtn = group.querySelector("._eli3_bd_logic_guidance");
      if (guidanceBtn) {
        guidanceBtn.onclick = function (ev) {
          ev.preventDefault();
          ev.stopPropagation();
          onGuidance(def.guidance, key);
        };
      }
      form.appendChild(group);
    });
  }

  // Single canonical evaluator from engine; opts.evalCondition wins
  // (init wires the bundle helper through), else fall back to inline.
  var _evalCondition = opts.evalCondition || function (cond, ans) {
    if (cond === "true") return true;
    var op = cond.indexOf("!=") !== -1 ? "!=" : "==";
    var parts = cond.split(op);
    if (parts.length < 2) return false;
    var k = parts[0].trim();
    var rhs = parts[1].split("||").map(function (t) { return t.trim().replace(/['"]/g, ""); });
    var actual = ans && ans[k];
    if (actual === undefined) return false;
    return op === "==" ? rhs.indexOf(actual) !== -1 : rhs.indexOf(actual) === -1;
  };
  function _updateVisibility() {
    var answers = {};
    form.querySelectorAll("._eli3_bd_logic_input").forEach(function (i) {
      answers[i.getAttribute("data-key")] = i.value;
    });
    Object.keys(deps).forEach(function (key) {
      var rules = deps[key] || [];
      var visible = rules.every(function (r) { return _evalCondition(r, answers); });
      var grp = form.querySelector('._eli3_bd_logic_group[data-key="' + key + '"]');
      if (grp) grp.style.display = visible ? "block" : "none";
    });
  }

  _renderInputs();
  root.appendChild(form);

  var actions = document.createElement("div");
  actions.className = "_eli3_bd_logic_actions";
  var gen = document.createElement("button");
  gen.className = "_eli3_bd_run_all";
  gen.innerHTML = "🚀 GENERATE DOCUMENT";
  gen.onclick = function () {
    var answers = {};
    form.querySelectorAll("._eli3_bd_logic_input").forEach(function (i) {
      answers[i.getAttribute("data-key")] = i.value;
    });
    onGenerate(answers);
  };
  actions.appendChild(gen);
  root.appendChild(actions);

  mount.appendChild(root);
  _updateVisibility();
}

// renderTemplateFillForm — Step 2 v3 port of v2 renderTemplateForm (line 6458).
// Lists placeholders with auto-expanding textareas + Locate buttons +
// optional AI Auto-Fill button when AGREEMENT_DATA is loaded.

view.renderTemplateFillForm:
function renderTemplateFillForm(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var placeholders = opts.placeholders || [];
  var sourceText = opts.sourceText || "";
  var sourceName = opts.sourceName || null;
  var onAutoFill = opts.onAutoFill || function () {};
  var onApply = opts.onApply || function () {};
  var onLocate = opts.onLocate || function () {};
  var onOarsLookup = opts.onOarsLookup || function () {};
  var onPaymentHelper = opts.onPaymentHelper || function () {};
  var onUpload = opts.onUpload || function () {};
  var onBack = opts.onBack || function () {};
  // 2026-05-19: prefill values (from activity restore) + change callback
  // (debounced, used by init.js to keep the activity-feed payload fresh
  // so back/restore round-trips the user's in-progress filling).
  var prefillValues = (opts && opts.prefillValues) || {};
  var onValuesChange = opts.onValuesChange || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _cleanLabel(ph) {
    var raw = ph.replace(/[\[\]{}]/g, "").replace(/^(\$!|\$|!)/, "");
    if (raw.indexOf("||") !== -1) {
      var parts = raw.split("||");
      return { label: parts[1].trim(), aiKey: parts[0].trim() };
    }
    return { label: raw, aiKey: raw };
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_fill";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">⚡ Auto-Fill Templates</div>' +
      '<div class="_eli3_bd_overview">' + placeholders.length + ' placeholder' + (placeholders.length === 1 ? "" : "s") + '</div>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;

  if (!placeholders.length) {
    var empty = document.createElement("div");
    empty.className = "_eli3_bd_fill_empty";
    var diag = opts.diag || null;
    var diagHtml = diag
      ? '<div class="_eli3_bd_fill_empty_diag">' +
          '<div class="_eli3_bd_fill_empty_diag_label">Scan result</div>' +
          '<div class="_eli3_bd_fill_empty_diag_val">' + diag.textLen.toLocaleString() + ' characters checked across body, headers, and footers</div>' +
        '</div>'
      : '';
    // 2026-05-20: premium empty-state. Eyebrow + large heading + supporting
    // copy + four example markers in their own card + tip + diag block.
    // Centered hero block, gold accent rail to match the rest of Build
    // Draft's chrome.
    empty.innerHTML =
      '<div class="_eli3_bd_fill_empty_hero">' +
        '<div class="_eli3_bd_fill_empty_icon">📭</div>' +
        '<div class="_eli3_bd_fill_empty_eyebrow">Nothing to fill</div>' +
        '<div class="_eli3_bd_fill_empty_title">No placeholders detected</div>' +
        '<div class="_eli3_bd_fill_empty_desc">' +
          'This document doesn\'t contain any ELI placeholder markers, so Step 2 has nothing to fill. ' +
          'Open a template that uses one of the supported marker syntaxes.' +
        '</div>' +
      '</div>' +
      '<div class="_eli3_bd_fill_empty_markers">' +
        '<div class="_eli3_bd_fill_empty_marker">' +
          '<code>[[Brackets]]</code>' +
          '<span class="_eli3_bd_fill_empty_marker_desc">Standard placeholder</span>' +
        '</div>' +
        '<div class="_eli3_bd_fill_empty_marker">' +
          '<code>{{Curlies}}</code>' +
          '<span class="_eli3_bd_fill_empty_marker_desc">Logic / DEF tags</span>' +
        '</div>' +
        '<div class="_eli3_bd_fill_empty_marker">' +
          '<code>$![Total Fee]</code>' +
          '<span class="_eli3_bd_fill_empty_marker_desc">Payment trigger</span>' +
        '</div>' +
        '<div class="_eli3_bd_fill_empty_marker">' +
          '<code>![Schedule]</code>' +
          '<span class="_eli3_bd_fill_empty_marker_desc">Payment schedule candidate</span>' +
        '</div>' +
      '</div>' +
      '<div class="_eli3_bd_fill_empty_tip">' +
        '<span class="_eli3_bd_fill_empty_tip_icon">💡</span>' +
        '<span>Open <b>Templates</b> from the Build Draft hub to load a saved one, or paste a template into the active document.</span>' +
      '</div>' +
      diagHtml;
    root.appendChild(empty);
    mount.appendChild(root);
    return;
  }

  // AGREEMENT data summary + Auto-Fill button if loaded
  if (sourceText) {
    var loadedWrap = document.createElement("div");
    loadedWrap.className = "_eli3_bd_fill_loaded_wrap";
    loadedWrap.innerHTML =
      '<div class="_eli3_bd_fill_loaded">' +
        '<div class="_eli3_bd_fill_loaded_main">' +
          '<div class="_eli3_bd_fill_loaded_label">LOADED SOURCE</div>' +
          '<div class="_eli3_bd_fill_loaded_name">📄 ' + _esc(sourceName || "OARS data") + '</div>' +
        '</div>' +
        '<button class="_eli3_bd_fill_autofill_btn">' +
          '<span class="_eli3_bd_fill_autofill_icon">⚡</span>' +
          '<span class="_eli3_bd_fill_autofill_label">AUTO-FILL</span>' +
        '</button>' +
      '</div>' +
      '<div class="_eli3_bd_fill_status" hidden></div>';
    root.appendChild(loadedWrap);
    var autoBtn = loadedWrap.querySelector("._eli3_bd_fill_autofill_btn");
    var btnLabel = loadedWrap.querySelector("._eli3_bd_fill_autofill_label");
    var btnIcon  = loadedWrap.querySelector("._eli3_bd_fill_autofill_icon");
    var status = loadedWrap.querySelector("._eli3_bd_fill_status");
    autoBtn.onclick = function () {
      autoBtn.disabled = true;
      autoBtn.classList.add("_eli3_bd_fill_autofill_btn_filling");
      btnIcon.textContent = "⏳";
      btnLabel.textContent = "Filling…";
      status.hidden = false;
      status.textContent = "Analyzing data…";
      onAutoFill(placeholders, function (mapping, err) {
        autoBtn.disabled = false;
        autoBtn.classList.remove("_eli3_bd_fill_autofill_btn_filling");
        btnIcon.textContent = "⚡";
        btnLabel.textContent = "AUTO-FILL";
        if (err) { status.textContent = "❌ " + (err.message || "Error"); return; }
        var inputs = root.querySelectorAll("._eli3_bd_fill_input");
        var filled = 0;
        inputs.forEach(function (inp) {
          var v = mapping[inp.dataset.target] || mapping[inp.dataset.aiKey];
          inp.classList.remove("_bd_filled", "_bd_missing");
          if (v) {
            inp.value = v;
            inp.classList.add("_bd_filled");
            filled++;
            inp.style.height = "auto";
            inp.style.height = inp.scrollHeight + "px";
          } else {
            inp.classList.add("_bd_missing");
          }
        });
        var missing = inputs.length - filled;
        status.textContent = "✅ Filled " + filled + " · ❌ Missing " + missing;
      });
    };
  } else {
    // No source loaded — drop-zone for .docx/.txt/.csv/.json
    var dropZone = document.createElement("div");
    dropZone.className = "_eli3_bd_fill_drop";
    dropZone.innerHTML =
      '<div class="_eli3_bd_fill_drop_icon">📂</div>' +
      '<div class="_eli3_bd_fill_drop_title">Import Data Source</div>' +
      '<div class="_eli3_bd_fill_drop_desc">Click to upload (.docx, .txt, .csv, .json)</div>';
    var fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.accept = ".docx,.txt,.csv,.json,application/pdf";
    fileInput.style.display = "none";
    dropZone.onclick = function () { fileInput.click(); };
    fileInput.onchange = function (e) {
      var f = e.target.files && e.target.files[0];
      if (!f) return;
      dropZone.innerHTML =
        '<div class="_eli3_bd_fill_drop_icon">⏳</div>' +
        '<div class="_eli3_bd_fill_drop_title">Reading ' + _esc(f.name) + '…</div>';
      onUpload(f, placeholders, function (mapping, err) {
        if (err) {
          dropZone.innerHTML =
            '<div class="_eli3_bd_fill_drop_icon">❌</div>' +
            '<div class="_eli3_bd_fill_drop_title">' + _esc(err.message || "Error") + '</div>';
          return;
        }
        var inputs = root.querySelectorAll("._eli3_bd_fill_input");
        var filled = 0;
        inputs.forEach(function (inp) {
          var v = mapping[inp.dataset.target] || mapping[inp.dataset.aiKey];
          inp.classList.remove("_bd_filled", "_bd_missing");
          if (v) {
            inp.value = v;
            inp.classList.add("_bd_filled");
            filled++;
            inp.style.height = "auto";
            inp.style.height = inp.scrollHeight + "px";
          } else {
            inp.classList.add("_bd_missing");
          }
        });
        dropZone.innerHTML =
          '<div class="_eli3_bd_fill_drop_icon">✅</div>' +
          '<div class="_eli3_bd_fill_drop_title">Filled ' + filled + ' / ' + inputs.length + ' fields</div>';
      });
    };
    root.appendChild(dropZone);
    root.appendChild(fileInput);
  }

  // Per-placeholder fill rows
  var formContainer = document.createElement("div");
  formContainer.className = "_eli3_bd_fill_form";
  // 2026-05-19: debounce helper for onValuesChange so we don't fire
  // a full state-snapshot on every keystroke.
  var _changeTimer = null;
  function _emitChange() {
    if (_changeTimer) clearTimeout(_changeTimer);
    _changeTimer = setTimeout(function () {
      _changeTimer = null;
      try {
        var values = {};
        formContainer.querySelectorAll("._eli3_bd_fill_input").forEach(function (inp) {
          values[inp.dataset.target] = inp.value;
        });
        onValuesChange(values);
      } catch (_e) {}
    }, 400);
  }
  // 2026-05-20: payment helper detection — ONLY ![[ placeholders.
  // Narrower than the prior "any payment-keyword label" gate — the
  // helper is tied to the specific ![[…]] payment-schedule-candidate
  // marker convention. [[Payment Terms]] etc. won't trigger it.
  function _isPaymentPlaceholder(ph) {
    return /^!\[\[/.test(String(ph || ""));
  }
  placeholders.forEach(function (ph) {
    var ck = _cleanLabel(ph);
    var isPayment = _isPaymentPlaceholder(ph);
    var wrap = document.createElement("div");
    wrap.className = "_eli3_bd_fill_field" + (isPayment ? " _eli3_bd_fill_field_payment" : "");
    // 2026-05-20: Payment Helper button sits IMMEDIATELY after the
    // label text (inline with it), not grouped with the right-side
    // action buttons. Reads as "this field's helper" rather than
    // a generic row action.
    wrap.innerHTML =
      '<label class="_eli3_bd_fill_label">' +
        '<span class="_eli3_bd_fill_label_text">' +
          '<span>' + _esc(ck.label) + '</span>' +
          (isPayment
            ? '<button class="_eli3_bd_fill_payment" type="button" title="Open the payment schedule helper to build the due-as-follows string before applying — the dialog won\'t pop up later if this field is filled.">💰 PAYMENT HELPER</button>'
            : "") +
        '</span>' +
        '<span class="_eli3_bd_fill_label_btns">' +
          '<button class="_eli3_bd_fill_locate" type="button" title="Scroll the Word document to this placeholder">📍 LOCATE IN DOC</button>' +
          '<button class="_eli3_bd_fill_oars" type="button" title="Open the processed OARS data viewer and jump to the field that matches this placeholder">🔎 OARS LOOKUP</button>' +
        '</span>' +
      '</label>';
    var inp = document.createElement("textarea");
    inp.className = "_eli3_bd_fill_input";
    inp.dataset.target = ph;
    inp.dataset.aiKey = ck.aiKey;
    inp.placeholder = "Enter " + ck.label;
    inp.rows = 1;
    // 2026-05-19: pre-populate value from prefillValues (activity-feed
    // restore). Lookup by full placeholder OR by aiKey so saved values
    // round-trip regardless of which form the placeholder was stored as.
    var pre = (prefillValues[ph] != null ? prefillValues[ph] : prefillValues[ck.aiKey]);
    if (pre != null && pre !== "") {
      inp.value = String(pre);
      inp.classList.add("_bd_filled");
    }
    inp.addEventListener("input", function () {
      this.style.height = "auto";
      this.style.height = this.scrollHeight + "px";
      // Live filled/empty visual state — green left-bar when non-empty,
      // base when cleared. Removes the gap where the user typed but
      // didn't yet submit, so the "is this filled?" signal is instant.
      if (this.value && this.value.trim()) {
        this.classList.add("_bd_filled");
        this.classList.remove("_bd_missing");
      } else {
        this.classList.remove("_bd_filled");
      }
      _emitChange();
    });
    wrap.appendChild(inp);
    var locBtn = wrap.querySelector("._eli3_bd_fill_locate");
    locBtn.onclick = function () { onLocate(ph, inp.value); };
    var oarsBtn = wrap.querySelector("._eli3_bd_fill_oars");
    if (oarsBtn) oarsBtn.onclick = function () { onOarsLookup(ph, ck.aiKey, ck.label); };
    var payBtn = wrap.querySelector("._eli3_bd_fill_payment");
    if (payBtn) payBtn.onclick = function () {
      onPaymentHelper(ph, ck.label, inp.value, function (formattedString) {
        if (formattedString == null) return;
        inp.value = formattedString;
        inp.classList.add("_bd_filled");
        inp.classList.remove("_bd_missing");
        inp.style.height = "auto";
        inp.style.height = inp.scrollHeight + "px";
        _emitChange();
      });
    };
    formContainer.appendChild(wrap);
  });
  root.appendChild(formContainer);
  // 2026-05-19: after first paint, auto-fit any prefilled textarea's
  // height and emit one initial change so the activity entry's payload
  // reflects what's currently on screen.
  setTimeout(function () {
    formContainer.querySelectorAll("._eli3_bd_fill_input").forEach(function (inp) {
      if (inp.value) {
        inp.style.height = "auto";
        inp.style.height = inp.scrollHeight + "px";
      }
    });
  }, 0);

  var actions = document.createElement("div");
  actions.className = "_eli3_bd_logic_actions";
  var apply = document.createElement("button");
  apply.className = "_eli3_bd_run_all";
  apply.innerHTML = "FILL ALL FIELDS";
  apply.onclick = function () {
    var values = {};
    var missing = [];
    formContainer.querySelectorAll("._eli3_bd_fill_input").forEach(function (inp) {
      var v = inp.value;
      values[inp.dataset.target] = v;
      inp.classList.remove("_bd_filled", "_bd_missing");
      if (!v || !String(v).trim()) {
        inp.classList.add("_bd_missing");
        var lbl = inp.dataset.aiKey || inp.dataset.target;
        missing.push(_esc(lbl));
      }
    });
    // FROM v2 applyTemplateValues missing-fields warning (line 6960).
    // Skip dialog if no missing or showEliDialog isn't loaded.
    if (missing.length && typeof showEliDialog === "function") {
      showEliDialog({
        variant: "warning",
        tier: "premium",
        icon: "⚠️",
        title: "Missing Fields",
        body:
          '<div style="font:500 12px/1.5 \'Inter\',sans-serif;color:#475569;margin-bottom:8px;">' +
            'These ' + missing.length + ' field' + (missing.length === 1 ? '' : 's') + ' are empty:' +
          '</div>' +
          '<div style="max-height:180px;overflow-y:auto;padding:8px 12px;background:#fef3c7;border-left:3px solid #f59e0b;font:600 12px/1.6 \'Inter\',sans-serif;color:#78350f;">' +
            missing.join("<br>") +
          '</div>',
        primary: {
          label: "I'll Fix Them",
          onclick: function () {
            var firstMissing = formContainer.querySelector("._eli3_bd_fill_input._bd_missing");
            if (firstMissing) {
              firstMissing.scrollIntoView({ behavior: "smooth", block: "center" });
              try { firstMissing.focus(); } catch (e) {}
            }
          },
        },
        secondary: {
          label: "Skip & Fill",
          onclick: function () { onApply(values); },
        },
      });
      return;
    }
    onApply(values);
  };
  actions.appendChild(apply);
  root.appendChild(actions);

  mount.appendChild(root);
}

// renderBracketCleaner — Step 2 v3-native port of v2's showBracketCleaner
// (line 22706). Lists [bracket] placeholders + locate buttons + 💡 SOW
// helper trigger when a cleaner_rules match exists.

view.renderBracketCleaner:
function renderBracketCleaner(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var brackets = (opts.brackets && opts.brackets.items) || [];
  var financial = (opts.financial && opts.financial.items) || [];
  var cleanerRules = opts.cleanerRules || [];
  var onBack = opts.onBack || function () {};
  var onLocate = opts.onLocate || function () {};
  var onSowHelper = opts.onSowHelper || function () {};
  var onDone = opts.onDone || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  // Find a cleaner_rules match for an inner bracket label.
  function _ruleFor(inner) {
    var lower = String(inner || "").toLowerCase();
    for (var i = 0; i < cleanerRules.length; i++) {
      var r = cleanerRules[i];
      if (!r || !r.id || r.id.indexOf("__") === 0) continue;
      if (lower.indexOf(String(r.id).toLowerCase()) !== -1) return r;
      if (r.title && lower.indexOf(String(r.title).toLowerCase().replace(/[^a-z]/g, "")) !== -1) return r;
    }
    return null;
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_cleaner";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">📝 Fill Placeholders</div>' +
      '<div class="_eli3_bd_overview">' + brackets.length + ' bracket' + (brackets.length === 1 ? "" : "s") +
        (financial.length ? ' · ' + financial.length + ' $ amount' + (financial.length === 1 ? "" : "s") : '') +
      '</div>' +
    '</div>' +
    '<div class="_eli3_bd_cleaner_intro">' +
      (brackets.length || financial.length
        ? '<b>' + brackets.length + ' placeholder' + (brackets.length === 1 ? "" : "s") + '</b> + ' +
          '<b>' + financial.length + ' $ amount' + (financial.length === 1 ? "" : "s") + '</b> detected. ' +
          'Use Locate to jump to each in Word; click 💡 for SOW Helper suggestions when available.'
        : 'No placeholders or $ amounts detected in the body.') +
    '</div>' +
    '<div class="_eli3_bd_cleaner_list" id="_eli3_bd_cleaner_list"></div>' +
    '<div class="_eli3_bd_cleaner_done">' +
      '<button class="_eli3_bd_run_all" id="_eli3_bd_done_btn">I\'M DONE ➜</button>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;
  root.querySelector("#_eli3_bd_done_btn").onclick = onDone;

  var list = root.querySelector("#_eli3_bd_cleaner_list");
  // Combined list: brackets first, $ amounts after.
  var rows = brackets.map(function (b) { return { type: "bracket", text: b.text, inner: b.inner, rule: _ruleFor(b.inner) }; })
    .concat(financial.map(function (f) { return { type: "financial", text: f.text, inner: f.text }; }));
  if (!rows.length) {
    var empty = document.createElement("div");
    empty.className = "_eli3_bd_cleaner_empty";
    empty.textContent = "Nothing to review.";
    list.appendChild(empty);
  } else {
    rows.forEach(function (r, idx) {
      var row = document.createElement("div");
      row.className = "_eli3_bd_cleaner_row";
      var typeTag = r.type === "financial"
        ? '<span class="_eli3_bd_cleaner_tag _eli3_bd_cleaner_tag_money">$</span>'
        : '<span class="_eli3_bd_cleaner_tag">[</span>';
      var helperBtn = r.rule
        ? '<button class="_eli3_bd_action_btn _eli3_bd_action_help" data-eli-bd-help="' + idx + '">💡 Suggestions</button>'
        : '';
      row.innerHTML =
        '<div class="_eli3_bd_cleaner_left">' +
          typeTag +
          '<span class="_eli3_bd_cleaner_text">' + _esc(r.text) + '</span>' +
        '</div>' +
        '<div class="_eli3_bd_cleaner_right">' +
          '<button class="_eli3_bd_action_btn _eli3_bd_action_locate" data-eli-bd-locate="' + idx + '">📍 Locate</button>' +
          helperBtn +
        '</div>';
      row.querySelector("[data-eli-bd-locate]").onclick = function () { onLocate(r); };
      var help = row.querySelector("[data-eli-bd-help]");
      if (help) help.onclick = function () { onSowHelper(r); };
      list.appendChild(row);
    });
  }
  mount.appendChild(root);
}

// renderSowHelper — modal overlay listing cleaner_rules options for a
// detected bracket. FROM v2 showGenericCleanerHelper (line 22780).
// Uses showEliDialog for tier:premium consistency.

view.renderSowHelper:
function renderSowHelper(opts) {
  var rule = opts.rule || {};
  var target = opts.target || "";
  var onPick = opts.onPick || function () {};
  if (typeof showEliDialog !== "function") {
    if (window.eli && window.eli.log) window.eli.log.event("tool", "build_draft_no_dialog", {});
    if (typeof showToast === "function") showToast("Dialog primitive unavailable", "err");
    return;
  }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  var optsHtml = (rule.options || []).map(function (o, i) {
    return '<button class="_eli3_bd_sow_option" data-eli-bd-sow-pick="' + i + '">' +
      '<span class="_eli3_bd_sow_option_label">' + _esc(o.label) + '</span>' +
      '<span class="_eli3_bd_sow_option_desc">' + _esc(o.desc || o.text || "") + '</span>' +
    '</button>';
  }).join("");
  showEliDialog({
    variant: "info",
    tier: "premium",
    icon: "💡",
    title: "SOW Helper · " + (rule.title || rule.id || "Suggestions"),
    body:
      '<div class="_eli3_bd_sow_intro">Select a clause to replace ' +
      '<b>' + _esc(target) + '</b>:</div>' +
      '<div class="_eli3_bd_sow_options">' + optsHtml + '</div>',
    secondary: { label: "Cancel" },
    onMount: function (overlay) {
      overlay.querySelectorAll("[data-eli-bd-sow-pick]").forEach(function (btn) {
        btn.onclick = function () {
          var i = parseInt(btn.getAttribute("data-eli-bd-sow-pick"), 10);
          var picked = (rule.options || [])[i];
          if (picked) onPick(picked);
          if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
        };
      });
    },
  });
}

// renderTemplatesView — FROM v2 showFileNameSettings (line 20740). Two
// tabs: FILE NAMING (pattern config + highlight toggle) and XML
// TEMPLATES (per-agreement-type library + active-doc save + bulk
// import/export + per-row Load/Delete).

view.renderTemplatesView:
function renderTemplatesView(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var initialTab = opts.tab || "templates"; // "naming" | "templates"
  var patterns = opts.patterns || {
    colgate: "[Ref] - CP-[Party] -- [Type] (DRAFT [Date])",
    hills: "[Ref] - HPN-[Party] -- [Type] (DRAFT [Date])",
  };
  var highlightFill = !!opts.highlightFill;
  var templates = opts.templates || [];
  var onSavePatterns = opts.onSavePatterns || function () {};
  var onSaveActiveDoc = opts.onSaveActiveDoc || function () {};
  var onLoadTemplate = opts.onLoadTemplate || function () {};
  var onDeleteTemplate = opts.onDeleteTemplate || function () {};
  var onBulkImport = opts.onBulkImport || function () {};
  var onBack = opts.onBack || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_tpl";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">⚙️ Build Draft Settings</div>' +
      '<div class="_eli3_bd_overview">' + templates.length + ' template' + (templates.length === 1 ? "" : "s") + '</div>' +
    '</div>' +
    '<div class="_eli3_bd_tpl_tabs">' +
      '<button class="_eli3_bd_tpl_tab" data-tab="naming">FILE NAMING</button>' +
      '<button class="_eli3_bd_tpl_tab" data-tab="templates">XML TEMPLATES</button>' +
    '</div>' +
    '<div class="_eli3_bd_tpl_body" id="_eli3_bd_tpl_body"></div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;
  var body = root.querySelector("#_eli3_bd_tpl_body");

  function _setActiveTab(name) {
    root.querySelectorAll("._eli3_bd_tpl_tab").forEach(function (t) {
      t.classList.toggle("_eli3_bd_tpl_tab_active", t.getAttribute("data-tab") === name);
    });
    if (name === "naming") _renderNaming();
    else _renderTemplates();
  }
  root.querySelectorAll("._eli3_bd_tpl_tab").forEach(function (t) {
    t.onclick = function () { _setActiveTab(t.getAttribute("data-tab")); };
  });

  function _renderNaming() {
    body.innerHTML =
      '<div class="_eli3_bd_tpl_hint">' +
        '<b>Tokens:</b> <code>[Ref]</code> <code>[Party]</code> <code>[Type]</code> <code>[Date]</code>' +
      '</div>' +
      '<label class="_eli3_bd_tpl_label">Colgate Pattern</label>' +
      '<input type="text" id="_eli3_bd_pat_colgate" class="_eli3_bd_tpl_input" value="' + _esc(patterns.colgate) + '">' +
      '<label class="_eli3_bd_tpl_label">Hill\'s Pattern</label>' +
      '<input type="text" id="_eli3_bd_pat_hills" class="_eli3_bd_tpl_input" value="' + _esc(patterns.hills) + '">' +
      '<label class="_eli3_bd_tpl_check">' +
        '<input type="checkbox" id="_eli3_bd_chk_highlight"' + (highlightFill ? " checked" : "") + '>' +
        '<span>🖊️ Highlight filled fields</span>' +
      '</label>' +
      '<button class="_eli3_bd_tpl_save_btn" id="_eli3_bd_save_naming">💾 Save Patterns</button>' +
      // Revised-draft naming explainer — documents the entity-aware
      // edits suffix used by the OARS Copy Filename button in the
      // session-feed header. Suffix follows the entity prefix in the
      // pattern above: Colgate → "CP edits", Hill's → "HPN edits".
      '<div class="_eli3_bd_tpl_naming_explain">' +
        '<div class="_eli3_bd_tpl_naming_explain_head">📋 REVISED-DRAFT NAMING</div>' +
        '<div class="_eli3_bd_tpl_naming_explain_body">' +
          'When you open a doc that already has OARS data attached and click <strong>Copy Filename</strong> in the session-feed header, ELI generates a filename using the patterns above but swaps the <code>(DRAFT [Date])</code> suffix for an entity-specific edits label. The suffix mirrors the entity prefix on the filename: <strong>CP-</strong> docs become <code>(CP edits …)</code>, <strong>HPN-</strong> docs become <code>(HPN edits …)</code>.' +
          '<div class="_eli3_bd_tpl_naming_explain_examples">' +
            '<div><span class="_eli3_bd_naming_eg_label">New draft (Colgate):</span> <code>12345 - CP-Acme Corp -- MSA <strong>(DRAFT 05.16.2026)</strong>.docx</code></div>' +
            '<div><span class="_eli3_bd_naming_eg_label">CP edits:</span> <code>12345 - CP-Acme Corp -- MSA <strong>(CP edits 05.16.2026)</strong>.docx</code></div>' +
            '<div><span class="_eli3_bd_naming_eg_label">New draft (Hill\'s):</span> <code>12345 - HPN-Acme Corp -- MSA <strong>(DRAFT 05.16.2026)</strong>.docx</code></div>' +
            '<div><span class="_eli3_bd_naming_eg_label">HPN edits:</span> <code>12345 - HPN-Acme Corp -- MSA <strong>(HPN edits 05.16.2026)</strong>.docx</code></div>' +
          '</div>' +
          'The signal is clear at a glance: <code>DRAFT</code> = first version out the door, <code>CP edits</code> / <code>HPN edits</code> = your team\'s response to a counterparty draft. Both honor whatever patterns you set above; only the trailing suffix differs (and the prefix follows the CP / HPN convention you already use for new drafts).' +
        '</div>' +
      '</div>';
    body.querySelector("#_eli3_bd_save_naming").onclick = function () {
      onSavePatterns({
        patterns: {
          colgate: body.querySelector("#_eli3_bd_pat_colgate").value,
          hills: body.querySelector("#_eli3_bd_pat_hills").value,
        },
        highlightFill: body.querySelector("#_eli3_bd_chk_highlight").checked,
      });
    };
  }

  function _renderTemplates() {
    body.innerHTML =
      '<div class="_eli3_bd_tpl_hint">Save the active document as a reusable template per agreement type.</div>' +
      '<div class="_eli3_bd_tpl_save">' +
        '<div class="_eli3_bd_tpl_save_label">FROM ACTIVE DOCUMENT</div>' +
        '<div class="_eli3_bd_tpl_save_radios">' +
          '<label><input type="radio" name="_eli3_bd_cat" value="MasterXML" checked> 🏗️ Core Template</label>' +
          '<label><input type="radio" name="_eli3_bd_cat" value="PriorAgreement"> 📂 Prior Agreement</label>' +
        '</div>' +
        '<input type="text" id="_eli3_bd_tpl_type" class="_eli3_bd_tpl_input" placeholder="Agreement Type (e.g. MSA Template)">' +
        '<input type="text" id="_eli3_bd_tpl_party" class="_eli3_bd_tpl_input _eli3_bd_tpl_hidden" placeholder="Party Name (Required for Prior Agreement)">' +
        '<button class="_eli3_bd_run_all" id="_eli3_bd_tpl_save_btn">💾 Save Active Doc as Template</button>' +
      '</div>' +
      '<div class="_eli3_bd_tpl_label">Saved Templates</div>' +
      '<div class="_eli3_bd_tpl_list" id="_eli3_bd_tpl_list"></div>' +
      '<div class="_eli3_bd_tpl_bulk">' +
        '<button class="_eli3_bd_tpl_bulk_btn" id="_eli3_bd_tpl_import">⬆️ Import JSON</button>' +
        '<input type="file" id="_eli3_bd_tpl_import_file" accept=".json" hidden>' +
        '<button class="_eli3_bd_tpl_bulk_btn" id="_eli3_bd_tpl_export">⬇️ Export All</button>' +
      '</div>';

    body.querySelectorAll('input[name="_eli3_bd_cat"]').forEach(function (radio) {
      radio.addEventListener("change", function () {
        var partyInp = body.querySelector("#_eli3_bd_tpl_party");
        partyInp.classList.toggle("_eli3_bd_tpl_hidden", this.value !== "PriorAgreement");
      });
    });
    body.querySelector("#_eli3_bd_tpl_save_btn").onclick = function () {
      var typeVal = body.querySelector("#_eli3_bd_tpl_type").value.trim();
      var partyVal = body.querySelector("#_eli3_bd_tpl_party").value.trim();
      var category = body.querySelector('input[name="_eli3_bd_cat"]:checked').value;
      if (!typeVal) { if (typeof showToast === "function") showToast("Enter an Agreement Type", "warn"); return; }
      if (category === "PriorAgreement" && !partyVal) {
        if (typeof showToast === "function") showToast("Prior Agreement requires a Party Name", "warn");
        return;
      }
      this.disabled = true;
      this.innerText = "⏳ Scanning…";
      onSaveActiveDoc({ type: typeVal, party: partyVal, category: category });
    };
    body.querySelector("#_eli3_bd_tpl_import").onclick = function () {
      body.querySelector("#_eli3_bd_tpl_import_file").click();
    };
    body.querySelector("#_eli3_bd_tpl_import_file").onchange = function (e) {
      var f = e.target.files && e.target.files[0];
      if (f) onBulkImport(f);
    };
    body.querySelector("#_eli3_bd_tpl_export").onclick = function () {
      var json = JSON.stringify(templates, null, 2);
      try {
        navigator.clipboard.writeText(json);
        if (typeof showToast === "function") showToast("📋 " + templates.length + " templates copied to clipboard", "ok");
      } catch (err) {
        if (typeof showToast === "function") showToast("Copy failed: " + (err && err.message), "err");
      }
    };

    var list = body.querySelector("#_eli3_bd_tpl_list");
    if (!templates.length) {
      list.innerHTML = '<div class="_eli3_bd_tpl_empty">No templates saved yet.</div>';
      return;
    }
    var sorted = templates.slice().sort(function (a, b) { return a.type === "MasterXML" ? -1 : 1; });
    list.innerHTML = "";
    sorted.forEach(function (t) {
      var isCore = t.type === "MasterXML";
      var icon = isCore ? "🏗️" : "📂";
      var badge = isCore ? "CORE" : "PRIOR";
      var size = (String(t.content || "").length / 1024).toFixed(1);
      var row = document.createElement("div");
      row.className = "_eli3_bd_tpl_row " + (isCore ? "_eli3_bd_tpl_row_core" : "_eli3_bd_tpl_row_prior");
      row.innerHTML =
        '<div class="_eli3_bd_tpl_row_main">' +
          '<div class="_eli3_bd_tpl_row_name">' + icon + " " + _esc(t.name || t.agreementType || "Untitled") + '</div>' +
          '<div class="_eli3_bd_tpl_row_meta">' + badge + ' · ' + size + ' KB · ' + _esc(t.savedDate || "") + '</div>' +
        '</div>' +
        '<button class="_eli3_bd_tpl_row_load" title="Load into doc">📥</button>' +
        '<button class="_eli3_bd_tpl_row_del" title="Delete">🗑️</button>';
      row.querySelector("._eli3_bd_tpl_row_load").onclick = function () { onLoadTemplate(t); };
      row.querySelector("._eli3_bd_tpl_row_del").onclick = function () { onDeleteTemplate(t); };
      list.appendChild(row);
    });
  }

  _setActiveTab(initialTab);
  mount.appendChild(root);
}

// renderSavePanel — FROM v2 showSaveAsManager (line 18930). REPURPOSED
// 2026-05-16: in-app save was unreliable (didn't carry OARS attach
// metadata, occasional sync failures). Replaced with a copy-paste
// flow: form generates a clean filename, big copy button puts it on
// the clipboard, instructions tell user to invoke Word's native Save
// As (F12 / Ctrl+Shift+S) and paste. Native save preserves everything
// the in-app save was losing. Skip → Email kept.

view.renderSavePanel:
function renderSavePanel(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var prefill = opts.prefill || {};
  var agTypes = opts.agTypes || []; // array of strings, e.g. ["NDA", "MSA", ...]
  var patterns = opts.patterns || {
    colgate: "[Ref] - CP-[Party] -- [Type] (DRAFT [Date])",
    hills: "[Ref] - HPN-[Party] -- [Type] (DRAFT [Date])",
  };
  // onSave kept for backward-compat but unused in the copy-paste flow.
  // The form's primary action is now copy-to-clipboard; the save path
  // (formerly onSave → _runSaveAsDocx) is bypassed entirely.
  var onSkip = opts.onSkip || function () {};
  var onSettings = opts.onSettings || function () {};
  var onBack = opts.onBack || function () {};
  var scanning = !!opts.scanning;

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_save";

  var typeOpts = '<option value="Other">Other (type below)</option>' +
    agTypes.map(function (t) { return '<option value="' + _esc(t) + '">' + _esc(t) + '</option>'; }).join("");

  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">📋 Build Filename</div>' +
      '<button class="_eli3_bd_save_settings" title="File-name settings">⚙️</button>' +
    '</div>' +
    (scanning
      ? '<div class="_eli3_bd_save_scanloader">' +
          '<div class="_eli3_bd_save_spinner"></div>' +
          '<div>Scanning document for metadata…</div>' +
        '</div>'
      : '') +
    '<div class="_eli3_bd_save_form">' +
      '<label class="_eli3_bd_save_label">CP Contracting Entity</label>' +
      '<select class="_eli3_bd_save_input" id="_eli3_bd_save_entity">' +
        '<option value="Colgate">Colgate-Palmolive Company</option>' +
        '<option value="Hills">Hill\'s Pet Nutrition</option>' +
      '</select>' +
      '<label class="_eli3_bd_save_label">Agreement Type</label>' +
      '<select class="_eli3_bd_save_input" id="_eli3_bd_save_type">' + typeOpts + '</select>' +
      '<input type="text" class="_eli3_bd_save_input _eli3_bd_save_hidden" id="_eli3_bd_save_typeManual" placeholder="Type Agreement Name…">' +
      '<label class="_eli3_bd_save_label">Third Party Name</label>' +
      '<input type="text" class="_eli3_bd_save_input" id="_eli3_bd_save_party" placeholder="e.g. Acme Corp">' +
      '<label class="_eli3_bd_save_label">CP Ref #</label>' +
      '<input type="text" class="_eli3_bd_save_input" id="_eli3_bd_save_ref" placeholder="e.g. 12345">' +
      // Big copy-target filename block — large monospace, click-to-select.
      '<div class="_eli3_bd_fn_block">' +
        '<div class="_eli3_bd_fn_label">YOUR FILENAME</div>' +
        '<div class="_eli3_bd_fn_value" id="_eli3_bd_save_preview" title="Click to select then copy">…</div>' +
        '<button class="_eli3_bd_fn_copy" id="_eli3_bd_save_copy" type="button">📋 Copy filename</button>' +
        '<div class="_eli3_bd_fn_copy_ack" id="_eli3_bd_save_copy_ack" style="display:none;">✓ Copied — <strong>click into your Word document</strong>, then hit <kbd>F12</kbd> (or <kbd>Ctrl+Shift+S</kbd>) and paste</div>' +
      '</div>' +
      // Step-by-step instructions.
      '<div class="_eli3_bd_fn_steps">' +
        '<div class="_eli3_bd_fn_steps_head">HOW TO SAVE</div>' +
        '<ol class="_eli3_bd_fn_steps_list">' +
          '<li>Click <strong>Copy filename</strong> above</li>' +
          '<li><strong>Click anywhere in your Word document first</strong> — this puts focus in Word (the taskpane swallows keystrokes otherwise)</li>' +
          '<li>Press <kbd>F12</kbd> (or <kbd>Ctrl+Shift+S</kbd>) to open <strong>Save As</strong></li>' +
          '<li>Paste (<kbd>Ctrl+V</kbd>) into the <em>File name</em> box</li>' +
          '<li>Pick your folder and click <strong>Save</strong></li>' +
        '</ol>' +
        '<div class="_eli3_bd_fn_why">Why copy-paste? Word\'s native Save As preserves everything (formatting, OARS attachments, doc settings). The in-app save dropped some of that.</div>' +
      '</div>' +
      '<div class="_eli3_bd_save_actions">' +
        '<button class="_eli3_bd_save_skip" id="_eli3_bd_save_skip" type="button">Skip → Email</button>' +
        '<button class="_eli3_bd_save_btn" id="_eli3_bd_save_btn" type="button">' +
          '<span class="_eli3_bd_save_btn_icon">📋</span>' +
          '<span class="_eli3_bd_save_btn_label">Copy + Continue → Email</span>' +
        '</button>' +
      '</div>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;
  root.querySelector("._eli3_bd_save_settings").onclick = onSettings;

  var entitySel = root.querySelector("#_eli3_bd_save_entity");
  var typeSel = root.querySelector("#_eli3_bd_save_type");
  var typeManual = root.querySelector("#_eli3_bd_save_typeManual");
  var partyInp = root.querySelector("#_eli3_bd_save_party");
  var refInp = root.querySelector("#_eli3_bd_save_ref");
  var previewEl = root.querySelector("#_eli3_bd_save_preview");

  // Apply prefill.
  if (prefill.entity) entitySel.value = prefill.entity;
  if (prefill.third_party_entity) partyInp.value = prefill.third_party_entity;
  if (prefill.cp_ref) refInp.value = prefill.cp_ref;
  // Match agreement type by case-insensitive substring.
  var prefType = (prefill.type || "").toLowerCase();
  if (prefType) {
    var found = false;
    for (var i = 0; i < typeSel.options.length; i++) {
      var v = typeSel.options[i].value.toLowerCase();
      if (v && v !== "other" && (prefType.indexOf(v) !== -1 || v.indexOf(prefType) !== -1)) {
        typeSel.selectedIndex = i; found = true; break;
      }
    }
    if (!found) {
      typeSel.value = "Other";
      typeManual.classList.remove("_eli3_bd_save_hidden");
      typeManual.value = prefill.type;
    }
  }

  // execChk removed 2026-05-12 — checkbox no longer rendered. Kept
  // var as null so the legacy guards (`execChk && execChk.checked`)
  // still short-circuit to false without touching the DOM.
  var execChk = null;

  function _genName() {
    var entity = entitySel.value;
    var type = typeSel.value === "Other" ? (typeManual.value || "Agreement") : typeSel.value;
    var party = partyInp.value.trim() || "Unknown";
    var ref = refInp.value.trim() || "Draft";
    var d = new Date();
    var date = (d.getMonth() + 1).toString().padStart(2, "0") + "."
             + d.getDate().toString().padStart(2, "0") + "."
             + d.getFullYear();
    var pat = entity === "Hills" ? patterns.hills : patterns.colgate;
    var name = pat.replace("[Ref]", ref).replace("[Party]", party).replace("[Type]", type).replace("[Date]", date);
    // FROM v2 line 19064 — execution-mode filename mutation. Strips
    // "(DRAFT <date>)" → "(<date>)", strips bare "DRAFT". The trailing
    // "(EXECUTION COPY)" suffix was removed 2026-05-12 (per user
    // request) — execution mode is still tracked in payload + email
    // seed, but no longer pollutes the filename.
    if (execChk && execChk.checked) {
      name = name.replace(/\(DRAFT\s+/gi, "(").replace(/\bDRAFT\b/gi, "").trim();
      name = name.replace(/\s+/g, " ");
    }
    return name + ".docx";
  }
  function _updatePreview() { previewEl.textContent = _genName(); }

  typeSel.onchange = function () {
    typeManual.classList.toggle("_eli3_bd_save_hidden", typeSel.value !== "Other");
    _updatePreview();
  };
  [entitySel, typeManual, partyInp, refInp].forEach(function (el) {
    el.addEventListener("input", _updatePreview);
    el.addEventListener("change", _updatePreview);
  });
  if (execChk) execChk.addEventListener("change", _updatePreview);
  _updatePreview();

  // Copy-to-clipboard with success acknowledgement. Falls back to a
  // selection-based execCommand("copy") on browsers where the async
  // clipboard API isn't available (Script Lab iframe quirks).
  function _copyFilename(showAck) {
    var name = _genName();
    var ackEl = root.querySelector("#_eli3_bd_save_copy_ack");
    function _onCopied() {
      if (!showAck || !ackEl) return;
      ackEl.style.display = "block";
      setTimeout(function () { if (ackEl) ackEl.style.display = "none"; }, 4000);
    }
    if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
      return navigator.clipboard.writeText(name).then(_onCopied).catch(function () {
        _copyViaSelection(name, _onCopied);
      });
    }
    _copyViaSelection(name, _onCopied);
    return Promise.resolve();
  }
  function _copyViaSelection(text, done) {
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.left = "-9999px";
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand("copy"); } catch (_e) {}
    document.body.removeChild(ta);
    if (typeof done === "function") done();
  }
  // Click the filename block itself to copy (large target).
  var fnValueEl = root.querySelector("#_eli3_bd_save_preview");
  if (fnValueEl) fnValueEl.onclick = function () {
    // Visually-select the text first (matches the "click to select"
    // tooltip + works as a fallback if clipboard write fails).
    var range = document.createRange();
    range.selectNodeContents(fnValueEl);
    var sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
    _copyFilename(true);
  };
  var copyBtn = root.querySelector("#_eli3_bd_save_copy");
  if (copyBtn) copyBtn.onclick = function () { _copyFilename(true); };

  // Primary action — copy + continue to email composer. Preserves the
  // formData hand-off (the email composer reads entity/type/party to
  // seed subject + body), just skips the .docx-write step.
  root.querySelector("#_eli3_bd_save_btn").onclick = function () {
    _copyFilename(true);
    // Brief delay so the user sees the "✓ Copied" ack before the
    // panel transitions out into the email step.
    setTimeout(function () {
      onSkip();  // → _runStep5Email — uses same hand-off as Skip path
    }, 300);
  };
  root.querySelector("#_eli3_bd_save_skip").onclick = onSkip;

  mount.appendChild(root);
}

view.renderStepStub:
function renderStepStub(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var step = opts.step || {};
  var onBack = opts.onBack || function () {};
  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back" title="Back">←</button>' +
      '<div class="_eli3_bd_title">' + (step.icon || "🛠️") + ' ' + (step.label || "Step") + '</div>' +
    '</div>' +
    '<div class="_eli3_bd_step_body">' +
      '<div class="_eli3_bd_step_pending">' +
        '<div class="_eli3_bd_step_pending_icon">🛠️</div>' +
        '<div class="_eli3_bd_step_pending_title">' + (step.label || "Step") + ' — pending v3 migration</div>' +
        '<div class="_eli3_bd_step_pending_desc">' +
          'This wizard step still runs in v2 mode. Migration to v3 lands once the engine ' +
          'logic is ported. For now, use Templates or Run All to invoke the v2 wizard.' +
        '</div>' +
      '</div>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;
  mount.appendChild(root);
}

jsonTools.init:
function init(eli) {
  // Magic-string constants — single source of truth across this tool.
  var SETTINGS_NAME = "AgreementDataName";
  var SETTINGS_TYPE = "AgreementDataType";
  var SETTINGS_DETAILS = "AgreementDataDetails";
  var BUS_OARS_FILE = "oars:file_selected";
  var BUS_OARS_CLEARED = "oars:cleared";
  var BUS_OARS_DETECTED = "oars:detected";
  var HF_TYPES = ["Primary", "FirstPage", "EvenPages"];
  var STEP2_APPLY_BATCH = 4; // keys per runRaw to keep under 100ms.

  // Wizard mode flag: when true, Step 1 → Step 2 → preSave → Step 3
  // chain auto-advances. Toggled by Run-All; cleared after Step 3 fires.
  var _wizardMode = false;

  // Kernel guarantees eli.events; if it's missing the kernel itself is
  // broken — fail loudly rather than paper over with a no-op shim.
  if (!eli.events || !eli.events.guard || !eli.events.safeAsync) {
    if (eli.log) eli.log.event("tool", "build_draft_missing_events", {});
    if (typeof showToast === "function") showToast("Build Draft failed: kernel events missing", "err");
    return;
  }
  var bundle = eli.tools._loaded["build_draft"];
  if (!bundle) return;
  var engineFns = bundle._eliEngineFns || {};
  var viewFns = bundle._eliViewFns || {};
  var analyze = engineFns.analyze;
  var evalLogicCondition = engineFns.evalLogicCondition;
  var extractTemplatePlaceholders = engineFns.extractTemplatePlaceholders;
  var renderHub = viewFns.renderHub;
  var renderStepStub = viewFns.renderStepStub;
  var renderBracketCleaner = viewFns.renderBracketCleaner;
  var renderSowHelper = viewFns.renderSowHelper;
  var renderLogicForm = viewFns.renderLogicForm;
  var renderTemplateFillForm = viewFns.renderTemplateFillForm;
  var renderTemplatesView = viewFns.renderTemplatesView;
  var renderSavePanel = viewFns.renderSavePanel;
  if (!analyze || !renderHub) {
    eli.log.event("tool", "build_draft_load_failed", { hasEngine: !!analyze, hasView: !!renderHub });
    return;
  }

  var providers = { host: eli.host, ai: eli.ai };

  // Per-session step completion tracker. Set when each step's success
  // path fires; read by the hub on every re-render so completed steps
  // show ✓ and the "you are here" dot advances to the first incomplete.
  // Reset on Clear OARS (user is starting over).
  var _bdCompleted = { logic: false, templates: false, error_review: false, save: false };

  // Footer-uploaded file cache. Kernel's status-bar DATA loader emits
  // "oars:file_selected" with {name, size, text}. Cache here so analyze()
  // sees the file contents on next render. FROM v2 finishFooterLoad
  // (line 14447) which set window.AGREEMENT_DATA = {name, text}.
  var _footerFile = null;
  // Rehydrate _footerFile from the kernel's current OARS state. Catches
  // the boot race where the kernel restored OARS from Office settings
  // and emitted oars:file_selected BEFORE this init ran (so the bus
  // listener missed the event). Without this, template auto-detection
  // falls back to body-text only and misses the footer-loaded data.
  try {
    // OARS data hub moved to the eli_oars tool in Batch 3 (2026-05-10).
    // Calls go through eli.dispatch("oars", *) channels. When the tool
    // isn't installed, dispatch returns undefined and build_draft
    // gracefully degrades to "no OARS available."
    var loaded = (eli.get && typeof eli.get("oars", "getState") === "function")
      ? eli.dispatch("oars", "getState")
      : null;
    if (loaded && loaded.text) {
      _footerFile = {
        name: loaded.name || "OARS DATA",
        size: loaded.size || (loaded.text ? loaded.text.length : 0),
        text: loaded.text,
        isBase64: !!loaded.isBase64,
        mime: loaded.mime || null,
        data: loaded.data || null,
      };
      eli.log.event("tool", "build_draft_oars_rehydrated", { source: loaded.source });
    }
  } catch (e) {
    eli.log.event("tool", "build_draft_oars_rehydrate_failed", { msg: e && e.message });
  }

  if (eli.bus && eli.bus.on) {
    eli.bus.on(BUS_OARS_FILE, function (payload) {
      _footerFile = payload ? {
        name: payload.name,
        size: payload.size,
        text: payload.text || "",
        // FROM v2 AGREEMENT_DATA shape — PDFs travel as base64 inline
        // data so eli.ai can pass them to Gemini's PDF reader.
        isBase64: !!payload.isBase64,
        mime: payload.mime || null,
        data: payload.data || null,
      } : null;
      // Pre-warm AI cache in the background (matches v2 finishFooterLoad
      // → runBackgroundAIAnalysis chain). Best-effort; failures are
      // logged but don't surface to the user.
      if (_footerFile && _footerFile.text) {
        _runBackgroundAIAnalysis(_footerFile.text);
      }
      var mount = document.getElementById("_eli3_dashboard_root");
      if (mount && mount.querySelector("._eli3_bd_root")) _show({ source: "footer_file" });
    });
    eli.bus.on(BUS_OARS_CLEARED, function () {
      _footerFile = null;
      var mount = document.getElementById("_eli3_dashboard_root");
      if (mount && mount.querySelector("._eli3_bd_root")) _show({ source: "footer_clear" });
    });
  }

  // Word.run: scan body + headers for OARS prefix; return text for parsing.
  function _scanDocForOars() {
    return eli.host.runRaw("build_draft:oars_scan", function (context) {
      var body = context.document.body;
      var section = context.document.sections.getFirst();
      var primaryHeader = section.getHeader("Primary");
      var firstHeader = section.getHeader("FirstPage");
      primaryHeader.load("text");
      firstHeader.load("text");
      body.load("text");
      return context.sync().then(function () {
        var headerText = ((primaryHeader.text || "") + " " + (firstHeader.text || "")).trim();
        var bodyText = body.text || "";
        var found = /\bOARS\b/i.test(headerText) || /\bOARS\b/i.test(bodyText);
        return { found: found, bodyText: bodyText, headerText: headerText };
      });
    }).catch(function (err) {
      eli.log.event("tool", "build_draft_scan_failed", { error: err && err.message });
      return { found: false, bodyText: "", headerText: "" };
    });
  }

  // Step 2 scan: gather text from body + every header/footer type so the
  // placeholder set covers the whole doc. FROM v2 runTemplateScan (6404).
  // Version stamp so logs prove which build is running. Bump on every
  // edit to _scanForFill so cache-staleness is unambiguous.
  var _SCAN_VERSION = "v3.4-forloop-traced";

  function _scanForFill() {
    eli.log.event("tool", "build_draft_fill_scan_invoked", { version: _SCAN_VERSION });
    return eli.host.runRaw("build_draft:fill_scan", function (context) {
      var body = context.document.body;
      var sections = context.document.sections;
      body.load("text");
      sections.load("items");
      return context.sync().then(function () {
        var stage = "before-stage1";
        try {
          stage = "compute-bodyLen";
          var bodyLen = (body.text || "").length;
          stage = "compute-sectionCount";
          var sectionCount = sections.items.length;
          stage = "log-stage1";
          eli.log.event("tool", "build_draft_fill_scan_stage1", {
            bodyLen: bodyLen, sectionCount: sectionCount, version: _SCAN_VERSION,
          });
          stage = "init-ranges";
          var ranges = [body];
          stage = "section-loop-start (HF_TYPES=" + (typeof HF_TYPES) + " len=" + (HF_TYPES && HF_TYPES.length) + ")";
          // Index-based iteration. Both sections.items and HF_TYPES use
          // .length + bracket access; never .forEach (some Office.js
          // versions don't expose forEach on typed collections).
          // 2026-05-19: linkage-aware HF scan. Pre-fix this loop pushed
          // all 3 header types + all 3 footer types per section. If
          // DifferentFirstPage / DifferentOddEven were OFF (the default),
          // those types are linked to Primary — same text returned 3×
          // per section → placeholders duplicated in fullText, leading
          // to "BASFBASFBASF"-style downstream output. Now we capture
          // every type but deduplicate by text equality before the join.
          for (var si = 0; si < sectionCount; si++) {
            stage = "section-" + si + "-fetch";
            var sec = sections.items[si];
            if (!sec) {
              eli.log.event("tool", "build_draft_section_undef", { si: si, sectionCount: sectionCount });
              continue;
            }
            for (var ti = 0; ti < HF_TYPES.length; ti++) {
              stage = "section-" + si + "-hf-" + ti;
              var t = HF_TYPES[ti];
              try { ranges.push(sec.getHeader(t)); }
              catch (e) { eli.log.event("tool", "build_draft_header_skip", { type: t, msg: e && e.message }); }
              try { ranges.push(sec.getFooter(t)); }
              catch (e) { eli.log.event("tool", "build_draft_footer_skip", { type: t, msg: e && e.message }); }
            }
          }
          stage = "ranges-load-text";
          for (var ri = 0; ri < ranges.length; ri++) ranges[ri].load("text");
          stage = "second-sync";
          return context.sync().then(function () {
            // De-duplicate by text content. Identical strings between
            // sibling H/F types (Primary vs FirstPage vs EvenPages) are
            // the smoking gun for linkage — keep one copy of each.
            var seen = {};
            var parts = [];
            for (var pi = 0; pi < ranges.length; pi++) {
              var txt = ranges[pi].text || "";
              if (!txt) continue;
              if (seen[txt]) continue;
              seen[txt] = true;
              parts.push(txt);
            }
            var fullText = parts.join("\n");
            var partLens = [];
            for (var pli = 0; pli < parts.length; pli++) partLens.push(parts[pli].length);
            eli.log.event("tool", "build_draft_fill_scan_stage2", {
              rangeCount: ranges.length,
              partLengths: partLens,
              fullLen: fullText.length,
              version: _SCAN_VERSION,
            });
            return fullText;
          });
        } catch (innerErr) {
          eli.log.event("tool", "build_draft_fill_scan_inner_throw", {
            stage: stage, msg: innerErr && innerErr.message, version: _SCAN_VERSION,
          });
          throw innerErr;
        }
      });
    }).catch(function (err) {
      // Surface the real error instead of silently returning "" — that
      // was masking Word.run failures and making textLen=0 ambiguous.
      eli.log.event("tool", "build_draft_fill_scan_failed", {
        msg: err && err.message,
        code: err && err.code,
        debugInfo: err && err.debugInfo,
        version: _SCAN_VERSION,
      });
      return "";
    });
  }

  // === AI cache layer (FROM v2 PROMPTS.saveAICacheToDB / saveDocToDB) ===
  // Caches per-source AI extraction so re-opens skip the AI call. Keyed
  // by a content hash so cache bust is automatic when source text changes.
  // Stored in STORE_CONFIG with id "_bd_ai_cache_<hash>" — leading "_"
  // marks it as kernel-internal (skipped by tool listings).
  // 2026-05-19: deterministic template id from (agreementType, type, party).
  // Replaces the legacy "bd_doc_" + Date.now() scheme — that gave each save
  // a unique timestamp id, so admin pushes never UPSERTed into colleagues'
  // existing rows (different id every time). With this slug-based id every
  // re-save / cross-machine push of the same (agreementType, type, party)
  // tuple lands on the same id → IDB UPSERT replaces cleanly.
  //
  // Slug rules:
  //   - lowercase
  //   - all non-alphanumeric → "_"
  //   - collapse repeats, trim ends
  // So "Non-Disclosure Agreement", "non disclosure agreement", and
  // "Non  Disclosure  Agreement" all collapse to "non_disclosure_agreement"
  // — variants the user almost always means as the same template.
  function _bd_slug(s) {
    return String(s == null ? "" : s)
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "")
      .replace(/_+/g, "_");
  }
  function _bd_templateId(agreementType, type, party) {
    return "bd_doc__" +
      (_bd_slug(agreementType) || "_") + "__" +
      (_bd_slug(type)          || "_") + "__" +
      (_bd_slug(party)         || "_");
  }
  // 2026-05-19: money formatter for placeholder values. OARS data ships
  // fees as raw numerics like "58925.0" — without this, that string goes
  // straight into the doc instead of "$58,925.00". Triggered on two
  // signals: explicit $-prefixed placeholders ($[ / $![) and plain
  // placeholders whose label contains money keywords (fee/payment/cost/
  // price/amount/usd/dollar). When the value parses as a pure number,
  // it's rendered with comma thousands separators + two decimals.
  function _bd_formatMoneyValue(raw) {
    var s = String(raw == null ? "" : raw).trim();
    if (!s) return null;
    var hadDollar = /^\$\s*/.test(s);
    s = s.replace(/^\$\s*/, "").replace(/,/g, "");
    // Must be a clean number; anything with letters/extra text → bail
    // (caller keeps raw value).
    if (!/^-?\d+(?:\.\d+)?$/.test(s)) return null;
    var n = parseFloat(s);
    if (!isFinite(n)) return null;
    var formatted = n.toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
    return { formatted: formatted, hadDollar: hadDollar };
  }
  function _bd_isLikelyMoneyPlaceholder(placeholder) {
    return /\b(fee|fees|payment|payments|cost|costs|price|amount|usd|dollar|dollars)\b/i.test(String(placeholder || ""));
  }
  function _bd_hashContent(text) {
    var s = String(text || "");
    var h = 0;
    for (var i = 0; i < s.length; i++) {
      h = ((h << 5) - h) + s.charCodeAt(i);
      h |= 0;
    }
    return "h" + (h >>> 0).toString(16);
  }

  function _bd_aiCacheKey(text) {
    return "_bd_ai_cache_" + _bd_hashContent(text);
  }

  function _bd_aiCacheGet(text) {
    var key = _bd_aiCacheKey(text);
    return eli.storage.get("config", key)
      .then(function (row) {
        if (row && row.value && Date.now() - (row.cachedAt || 0) < 7 * 24 * 60 * 60 * 1000) return row.value;
        return null;
      })
      .catch(function () { return null; });
  }

  function _bd_aiCachePut(text, value) {
    var key = _bd_aiCacheKey(text);
    // STORE_CONFIG's keyPath is "key" (kernel taskpane_v3.js:160) — NOT
    // "id" like every other store. The original v3 port wrote `{id: key,
    // ...}` which made every put throw "Evaluating the object store's
    // key path did not yield a value" and silently fail to cache. The
    // .catch swallowed the error so AI re-ran on every Step 2 click.
    return eli.storage.put("config", { key: key, value: value, cachedAt: Date.now() })
      .catch(function (e) {
        eli.log.event("tool", "build_draft_ai_cache_put_failed", { msg: e && e.message });
      });
  }

  // FROM v2 PROMPTS.runBackgroundAIAnalysis (line 1585). Pre-warms the
  // AI fill cache when OARS data loads so the user's Step 2 click is
  // instant. No-op if cache already populated for this content.
  function _runBackgroundAIAnalysis(sourceText) {
    if (!sourceText || sourceText.length < 50) return Promise.resolve(null);
    return _bd_aiCacheGet(sourceText).then(function (cached) {
      if (cached) {
        eli.log.event("tool", "build_draft_ai_prewarm_hit", {});
        return cached;
      }
      // Best-effort generic field extraction. The Step 2 fill flow uses
      // its own templateMap prompt for placeholder-specific mapping; this
      // pre-warms a broader field/data list for fast re-use.
      var prompt =
        "Analyze this document content.\n" +
        "TASK: Extract pairs of Field (Left) and Data (Right) from the document.\n" +
        "RETURN JSON ARRAY: [ { \"field\": \"...\", \"data\": \"...\" } ]\n" +
        "- Exclude rows where \"Data\" is empty.\n" +
        "- For tabular docs, Left col = Field, Right col = Data.\n\n" +
        "--- DOCUMENT ---\n" + sourceText;
      return eli.events.safeAsync(eli.ai.completeJSON(prompt, null, { maxTokens: 4000 }), "build_draft.prewarm")
        .then(function (json) {
          if (Array.isArray(json) && json.length) {
            return _bd_aiCachePut(sourceText, json).then(function () { return json; });
          }
          return null;
        })
        .catch(function (e) {
          eli.log.event("tool", "build_draft_ai_prewarm_failed", { msg: e && e.message });
          return null;
        });
    });
  }

  // FROM v2 persistAgreementState (line 14463). Saves type/name/details
  // into Office settings so future scans see the loaded state.
  function _persistAgreementState(name, type, details) {
    try {
      var s = (Office && Office.context && Office.context.document && Office.context.document.settings);
      if (!s) return Promise.resolve(false);
      if (name) s.set(SETTINGS_NAME, name);
      if (type) s.set(SETTINGS_TYPE, type);
      if (details) s.set(SETTINGS_DETAILS, details);
      return new Promise(function (resolve) {
        s.saveAsync(function () { resolve(true); });
      });
    } catch (e) {
      eli.log.event("tool", "build_draft_persist_failed", { msg: e && e.message });
      return Promise.resolve(false);
    }
  }

  // Full OARS clear: delegate to the eli_oars tool. After Batch 3 the
  // OARS hub owns the wipe + sentinel + bus emit + toast. If the tool
  // isn't installed (other team's deployment), build_draft just
  // best-effort wipes its own keys and moves on.
  function _clearAgreementState() {
    if (eli.get && typeof eli.get("oars", "clear") === "function") {
      eli.dispatch("oars", "clear");
      return Promise.resolve(true);
    }
    // Tool not installed — wipe what build_draft itself owns.
    try {
      var s = (Office && Office.context && Office.context.document && Office.context.document.settings);
      if (!s) return Promise.resolve(false);
      [SETTINGS_NAME, SETTINGS_TYPE, SETTINGS_DETAILS,
       "AgreementDataText", "AgreementDataSource"].forEach(function (k) {
        try { s.remove(k); } catch (e) {}
      });
      return new Promise(function (resolve) {
        s.saveAsync(function () { resolve(true); });
      });
    } catch (e) {
      eli.log.event("tool", "build_draft_clear_failed", { msg: e && e.message });
      return Promise.resolve(false);
    }
  }

  // FROM v2 showFileNameSettings → btnSaveActiveDoc (line 20852). Reads
  // body OOXML + per-section header/footer OOXML and bundles into a JSON
  // record for storage. Two short runRaw passes (body+sections, then
  // per-section HF) keep the budget tight on multi-section docs.
  function _captureActiveDocAsTemplate() {
    return eli.host.runRaw("build_draft:tpl_capture_body", function (context) {
      var doc = context.document;
      var bodyOoxml = doc.body.getOoxml();
      var sections = doc.sections;
      sections.load("items");
      return context.sync().then(function () {
        return { body: bodyOoxml.value, sectionCount: sections.items.length };
      });
    }).then(function (state) {
      // Per-section HF capture, one runRaw per section.
      var sectionsData = [];
      var chain = Promise.resolve();
      for (var i = 0; i < state.sectionCount; i++) {
        (function (idx) {
          chain = chain.then(function () {
            return eli.host.runRaw("build_draft:tpl_capture_section_" + idx, function (context) {
              var sections = context.document.sections;
              sections.load("items");
              return context.sync().then(function () {
                if (idx >= sections.items.length) return null;
                var sec = sections.items[idx];
                var grabs = {
                  primaryH: sec.getHeader("Primary").getOoxml(),
                  firstPageH: sec.getHeader("FirstPage").getOoxml(),
                  evenPagesH: sec.getHeader("EvenPages").getOoxml(),
                  primaryF: sec.getFooter("Primary").getOoxml(),
                  firstPageF: sec.getFooter("FirstPage").getOoxml(),
                  evenPagesF: sec.getFooter("EvenPages").getOoxml(),
                };
                return context.sync().then(function () {
                  return {
                    index: idx,
                    headers: {
                      primary: grabs.primaryH.value || "",
                      firstPage: grabs.firstPageH.value || "",
                      evenPages: grabs.evenPagesH.value || "",
                    },
                    footers: {
                      primary: grabs.primaryF.value || "",
                      firstPage: grabs.firstPageF.value || "",
                      evenPages: grabs.evenPagesF.value || "",
                    },
                  };
                });
              });
            }).then(function (data) { if (data) sectionsData.push(data); });
          });
        })(i);
      }
      return chain.then(function () {
        return { body: state.body, sections: sectionsData, savedDate: new Date().toISOString() };
      });
    });
  }

  // FROM v2 loadTemplateToWord (line 23762). Inserts a saved template
  // into the active doc. contentString is JSON ({body, sections}) for
  // full-fidelity OOXML templates, or plain text for legacy fallback.
  // Split into multiple short runRaw calls so each stays under 100ms:
  //   1.   Body OOXML insert
  //   2.   Per-section header/footer OOXML inserts (one runRaw per section)
  //   3a.  Body + tables font normalization
  //   3b.  Per-section H/F font normalization (one runRaw per section,
  //        all 3 HF types batched into 2 syncs vs 6)
  // 2026-05-21: skeleton-hybrid resolver state. Set during OARS auto-
  // launch (knows the detected agreement type) + manual-load paths.
  // Used by _resolveSkeleton at template-load time to pick the active
  // variant from &[…] boundaries.
  var _skeletonActiveVariant = null;
  function _setSkeletonVariant(name) {
    _skeletonActiveVariant = String(name || "").trim() || null;
  }

