        // that matches the placeholder's OARS-side key. The viewer
        // accepts an optional searchTerm; oars_loader highlights the
        // first match in the Processed tab (parsed fields grid) or
        // falls back to highlighting in the Unprocessed raw text.
        var term = String(aiKey || label || "").trim();
        if (!term) { showToast("No OARS key to look up.", "warn"); return; }
