  }

  // Read .docx (mammoth), .pdf (base64 inline-data for Gemini), or
  // plain text from a File object. PDFs callback with a sentinel object
  // so the AI fill path can route inlineData through to eli.ai.
  function _readFileForFill(file, cb) {
    var ext = String(file.name || "").split(".").pop().toLowerCase();
    var reader = new FileReader();
    if (ext === "docx" && window.mammoth && window.mammoth.extractRawText) {
      reader.onload = function () {
        window.mammoth.extractRawText({ arrayBuffer: reader.result })
          .then(function (r) { cb((r && r.value) || "", null); })
          .catch(function (err) { cb(null, err || new Error("docx parse failed")); });
      };
      reader.onerror = function () { cb(null, new Error("File read failed")); };
      reader.readAsArrayBuffer(file);
    } else if (ext === "pdf") {
      // Stash the base64 in _footerFile so _aiFillPlaceholders picks it
      // up via aiOpts.inlineData (matches v2 AGREEMENT_DATA shape).
      reader.onload = function () {
        var dataUrl = String(reader.result || "");
        var commaIdx = dataUrl.indexOf(",");
        var base64 = commaIdx === -1 ? dataUrl : dataUrl.substring(commaIdx + 1);
        _footerFile = {
          name: file.name, size: file.size, text: "[PDF: " + file.name + "]",
          isBase64: true, mime: "application/pdf", data: base64,
        };
        cb("[PDF: " + file.name + "]", null);
      };
      reader.onerror = function () { cb(null, new Error("PDF read failed")); };
      reader.readAsDataURL(file);
    } else {
      reader.onload = function () { cb(String(reader.result || ""), null); };
      reader.onerror = function () { cb(null, new Error("File read failed")); };
      reader.readAsText(file);
    }
  }

  // AI auto-fill: load templateMap prompt, format with placeholders +
  // file content, call eli.ai.completeJSON. FROM v2 templateMap usage.
  // Caches by (sourceText, placeholder-set) hash so re-clicks are free.
  // Defensive against cache poisoning: only caches non-empty mappings,
  // and treats empty cache hits as misses (re-runs the AI call).
  function _aiFillPlaceholders(placeholders, sourceText, cb) {
    eli.log.event("tool", "build_draft_ai_fill_start", {
      placeholderCount: placeholders ? placeholders.length : 0,
      sourceLen: sourceText ? sourceText.length : 0,
      hasFooterFile: !!_footerFile,
    });
    if (!sourceText) {
      cb(null, new Error("No data source loaded — upload an OARS file first"));
      return;
    }
    if (!placeholders.length) { cb({}, null); return; }
    var cleanKeys = placeholders.map(function (ph) {
      var raw = ph.replace(/[\[\]{}]/g, "").replace(/^(\$!|\$|!)/, "");
      if (raw.indexOf("||") !== -1) {
        var parts = raw.split("||");
        return { display: ph, ai: parts[0].trim() };
      }
      return { display: ph, ai: raw };
    });
    var cacheKey = sourceText + "|" + cleanKeys.map(function (k) { return k.ai; }).sort().join(",");

    function _isUseful(mapping) {
      if (!mapping || typeof mapping !== "object") return false;
      var keys = Object.keys(mapping);
      if (!keys.length) return false;
      // Reject mapping if every value is empty / null / "".
      return keys.some(function (k) {
        var v = mapping[k];
        return v != null && String(v).trim() !== "";
      });
    }
    function _mergeAndDeliver(mapping) {
      var merged = {};
      var hits = 0;
      cleanKeys.forEach(function (k) {
        if (mapping[k.ai] !== undefined) {
          merged[k.display] = mapping[k.ai];
          merged[k.ai] = mapping[k.ai];
          hits++;
        } else if (mapping[k.display] !== undefined) {
          merged[k.display] = mapping[k.display];
          hits++;
        }
      });
      eli.log.event("tool", "build_draft_ai_fill_done", {
        hits: hits, totalKeys: cleanKeys.length,
      });
      cb(merged, null);
    }

    function _runFresh() {
      eli.events.safeAsync(eli.storage.get("prompts", "templateMap"), "build_draft.prompt_load")
        .then(function (row) {
          if (!row || !row.text) {
            cb(null, new Error("templateMap prompt missing — install the AI Prompts data bundle"));
            return;
          }
          var prompt = eli.ai.formatPrompt(row.text, {
            placeholders: cleanKeys.map(function (k) { return k.ai; }).join("\n"),
            fileContent: sourceText,
          });
          // PDF base64 path: pass binary as a multimodal part array.
          // eli.ai._buildBody accepts prompt as array → forwards as
          // contents.parts. Text-only path passes prompt as string.
          var aiPrompt = prompt;
          if (_footerFile && _footerFile.isBase64 && _footerFile.mime && _footerFile.data) {
            aiPrompt = [
              { text: prompt },
              { inlineData: { mimeType: _footerFile.mime, data: _footerFile.data } },
            ];
          }
          eli.events.safeAsync(eli.ai.completeJSON(aiPrompt, null, { maxTokens: 4000 }), "build_draft.ai_fill")
            .then(function (mapping) {
              if (eli.wrongness) {
                eli.wrongness.capture("build_draft", {
                  flow: "ai_fill",
                  sourceTextLen: (sourceText || "").length,
                  placeholderCount: cleanKeys.length,
                  hasFooterPdf: !!(_footerFile && _footerFile.isBase64),
                }, mapping, {});
              }
              if (_isUseful(mapping)) {
                _bd_aiCachePut(cacheKey, mapping);
              } else {
                eli.log.event("tool", "build_draft_ai_fill_empty", {});
              }
              _mergeAndDeliver(mapping || {});
            })
            .catch(function (err) {
              eli.log.event("tool", "build_draft_ai_fill_call_failed", { msg: err && err.message });
              cb(null, err || new Error("AI fill failed"));
            });
        })
        .catch(function (err) { cb(null, err || new Error("Prompt load failed")); });
    }

    // Cache hit (only if it has actual data)?
    _bd_aiCacheGet(cacheKey).then(function (cached) {
      if (_isUseful(cached)) {
        eli.log.event("tool", "build_draft_ai_fill_cache_hit", {});
        _mergeAndDeliver(cached);
        return;
      }
      // Cached but empty — purge so we don't keep skipping the AI call
      // on subsequent reads.
      if (cached !== null && cached !== undefined) {
        eli.events.safeAsync(eli.storage.delete("config", _bd_aiCacheKey(cacheKey)), "build_draft.cache_purge");
        eli.log.event("tool", "build_draft_ai_cache_purged_empty", {});
      }
      _runFresh();
    }).catch(function () { _runFresh(); });
  }

  // FROM v2 applyTemplateValues runBatch (line 6854) + cleanupSpecificTags
  // (line 6906). Searches each placeholder across body + every header/footer
  // and replaces with the user's value; deletes leftover $! payment-trigger
  // tags after successful fill.
  function _runStep2Apply(values) {
    var keys = Object.keys(values).filter(function (k) { return values[k] && String(values[k]).trim(); });
    if (!keys.length) { showToast("No values to apply.", "warn"); return; }
    // Sort longest-first so e.g. "[[Client Name]]" matches before "[[Client]]".
    keys.sort(function (a, b) { return b.length - a.length; });
    showToast("⚙️ Applying " + keys.length + " field(s)…", "info");
    var tagsToKill = []; // $![ payment-trigger tags get fully deleted after.
    // FROM v2 line 6795: ![ (no $) markers are payment-schedule anchors.
    // After the standard batch lands, the schedule modal fires and
    // overwrites the first candidate with the "due as follows…" string.
    var paymentCandidates = [];
    var detectedFeeAmount = null;
    var totalCount = 0;
    var batches = [];
    for (var bi = 0; bi < keys.length; bi += STEP2_APPLY_BATCH) {
      batches.push(keys.slice(bi, bi + STEP2_APPLY_BATCH));
    }
    var batchChain = Promise.resolve();
    batches.forEach(function (batch) {
      batchChain = batchChain.then(function () {
        return _step2_applyBatch(batch, values, tagsToKill, paymentCandidates).then(function (n) { totalCount += n; });
      });
    });
    // FROM v2 line 6818: the $![ fee value seeds the modal's total.
    for (var fi = 0; fi < keys.length; fi++) {
      if (keys[fi].indexOf("$![") === 0) { detectedFeeAmount = String(values[keys[fi]]); break; }
    }
    return batchChain
      .then(function () {
        // FROM v2 line 6935: the ![ candidate marker was left in the doc
        // by _step2_applyBatch (it skips candidates so the marker stays
        // findable). EVERY exit path here MUST fill it — with the modal's
        // "due as follows: …" string, or the raw value as a fallback —
        // or the literal "![[…]]" marker survives in the document.
        var feeTrigger = paymentCandidates.length ? paymentCandidates[0] : null;
        if (!feeTrigger) return;
        var feeAmount = detectedFeeAmount || feeTrigger.val;
        // _fillCandidate passes null for paymentCandidates so this call
        // actually REPLACES the marker — the candidate-skip in
        // _step2_applyBatch only applies while collecting candidates.
        function _fillCandidate(text) {
          var o = {}; o[feeTrigger.target] = text;
          return _step2_applyBatch([feeTrigger.target], o, [], null)
            .then(function (c2) { totalCount += c2; })
            .catch(function (e) {
              eli.log.event("tool", "build_draft_payment_apply_failed", { msg: e && e.message });
            });
        }
        // 2026-05-20: skip the auto-modal entirely when the candidate's
        // input field is already populated (via the Payment Helper
        // button, manual typing, or auto-fill). User-supplied value
        // wins — modal would just be an unnecessary interruption.
        // Honors the rule: NO payment dialog if the field has content.
        var hasPrefill = !!(feeTrigger.val && String(feeTrigger.val).trim());
        if (hasPrefill) {
          return _fillCandidate(feeTrigger.val);
        }
        if (!feeAmount || typeof window.showPaymentScheduleModal !== "function") {
          if (window.ELI_DEBUG && typeof window.showPaymentScheduleModal !== "function") {
            console.warn("[build_draft] showPaymentScheduleModal missing — filling payment marker with raw value");
          }
          // No fee value / modal unavailable → fall back to raw value.
          return _fillCandidate(feeTrigger.val || "");
        }
        return new Promise(function (resolve) {
          window.showPaymentScheduleModal(feeAmount, feeTrigger.val || "", function (finalString) {
            // Apply → finalString is "due as follows: …". Cancel → null,
            // fall back to the raw value so the marker isn't left literal.
            _fillCandidate(finalString || feeTrigger.val || "").then(resolve);
          });
        });
      })
      .then(function () {
        if (!tagsToKill.length) return;
        return _step2_cleanupTags(tagsToKill).catch(function (e) {
          eli.log.event("tool", "build_draft_step2_cleanup_failed", { msg: e && e.message });
        });
      })
      .then(function () {
        // Count this as a built draft on the first templates-apply that
        // completes this session. The save-as-docx path was the only
        // increment point before — but most users build into the live
        // Word doc and stop there, so the stat never moved. The
        // `_bdCompleted.templates` flag prevents double-counting when
        // a user reapplies templates on the same draft session.
        if (!_bdCompleted.templates) _recordStatSafe("draftsCreated");
        _bdCompleted.templates = true;
        showToast("✅ Applied " + totalCount + " replacement(s)", "ok");
        if (eli.activity && eli.activity.add) {
          eli.activity.add({
            type: "build-draft", icon: "📝", label: "Build Draft · Fill",
            summary: totalCount + " replacement(s) applied",
            payload: { count: totalCount },
          });
        }
        // FROM v2 finishUp (line 6995): if highlights were applied, show
        // the verification dialog ("Looks Good — Remove Highlights")
        // BEFORE the pre-save scan. User reviews the yellow-highlighted
        // changes against source data, clicks Looks Good to clear, then
        // proceeds to bracket cleaner / Step 3.
        if (_highlightFillEnabled() && totalCount > 0) {
          _showVerificationDialog(totalCount, function () { _runPreSaveScan(); });
          return;
        }
        return _runPreSaveScan();
      })
      .catch(function (err) {
        _wizardMode = false;
        eli.log.event("tool", "build_draft_step2_apply_failed", { msg: err && err.message });
        showToast("Apply failed: " + (err && err.message), "err");
      });
  }

  // FROM v2 runPreSaveScan (line 22657). Searches for residual [...] bracket
