  // chose to leave). If any survive, opens the bracket cleaner; else
  // auto-advances per wizard mode.
  function _runPreSaveScan() {
    return eli.host.runRaw("build_draft:pre_save_scan", function (context) {
      var results = context.document.body.search("\\[[!]]@\\]", { matchWildcards: true });
      results.load("items");
      return context.sync().then(function () {
        for (var i = 0; i < results.items.length; i++) {
          results.items[i].font.load("color");
          results.items[i].load("text");
        }
        return context.sync().then(function () {
          var bracketsFound = [];
          for (var i2 = 0; i2 < results.items.length; i2++) {
            var item = results.items[i2];
            var color = (item.font.color || "").toLowerCase();
            var isRed = color === "#c62828" || color === "red" || color === "#ff0000";
            if (!isRed) {
              var text = item.text;
              if (text.indexOf("[[") === 0 && text.lastIndexOf("]]") !== text.length - 2) text = text + "]";
              bracketsFound.push({ text: text, inner: text.replace(/^\[+|\]+$/g, "") });
