        return _smartLocate(String(fallbackVal).trim(), null).then(function () {});
      }
      showToast("⚠️ Not found in document", "warn");
    }).catch(function (err) {
      eli.log.event("tool", "build_draft_locate_failed", { msg: err && err.message });
      showToast("Locate failed: " + (err && err.message), "err");
    });
  }

