}
._eli3_bd_tpl_hint {
  font: 500 11px/1.4 'Inter', sans-serif;
  color: #475569; background: #f9fafb;
  padding: 8px 10px; border: 1px solid #e2e8f0;
}
._eli3_bd_tpl_hint code {
  font: 600 11px/1 monospace;
  background: #fff; padding: 1px 4px;
  color: #1565c0; border: 1px solid #cbd5e1;
}
._eli3_bd_tpl_label {
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #0f172a; margin-top: 4px;
}
._eli3_bd_tpl_input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid #cbd5e1;
  background: #fff;
  font: 500 13px/1.3 'Inter', sans-serif;
  color: #0f172a;
  box-sizing: border-box;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._eli3_bd_tpl_input:focus {
  border-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21,101,192,0.18);
}
/* Scoped Save button for the File Naming settings panel — the
   dashboard `_eli3_bd_run_all` style is too large/loud for a quiet
   settings save. */
._eli3_bd_tpl_save_btn {
  align-self: flex-start;
  padding: 7px 14px;
  margin-top: 10px;
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid rgba(0,0,0,0.1);
  border-radius: 0;
  cursor: pointer;
  transition: transform .12s, box-shadow .12s;
}
._eli3_bd_tpl_save_btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 3px 10px rgba(21,101,192,0.28);
}
/* Revised-draft naming explainer (below the Save Patterns button). */
._eli3_bd_tpl_naming_explain {
  margin-top: 16px;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #1565c0;
  background: #f8fafc;
}
._eli3_bd_tpl_naming_explain_head {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #1e3a8a;
  background: #eff6ff;
  padding: 8px 12px;
  border-bottom: 1px solid #e2e8f0;
}
._eli3_bd_tpl_naming_explain_body {
  padding: 12px;
  font-size: 11px;
  line-height: 1.6;
  color: #0f172a;
}
._eli3_bd_tpl_naming_explain_body code {
  font-family: Consolas, monospace;
  background: #fff;
  border: 1px solid #cbd5e1;
  padding: 1px 5px;
  color: #1e3a8a;
  border-radius: 2px;
}
._eli3_bd_tpl_naming_explain_body strong {
  color: #b45309;
  background: #fef3c7;
  padding: 0 3px;
  border-radius: 2px;
}
._eli3_bd_tpl_naming_examples {
  margin: 10px 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
._eli3_bd_naming_eg_label {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #475569;
  display: inline-block;
  min-width: 70px;
}
._eli3_bd_tpl_check {
  display: flex; align-items: center; gap: 8px;
  font: 600 12px/1.3 'Inter', sans-serif;
  color: #0f172a; cursor: pointer;
  padding: 8px 0; border-top: 1px dashed #cbd5e1; margin-top: 4px;
}
._eli3_bd_tpl_save {
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  border-left: 4px solid #1565c0;
  padding: 10px 12px;
  display: flex; flex-direction: column; gap: 8px;
}
._eli3_bd_tpl_save_label {
  font: 800 9px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  color: #1e3a8a;
}
._eli3_bd_tpl_save_radios {
  display: flex; gap: 14px;
  font: 600 12px/1.2 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_bd_tpl_save_radios label {
  display: inline-flex; align-items: center; gap: 6px; cursor: pointer;
}
._eli3_bd_tpl_hidden { display: none !important; }
._eli3_bd_tpl_list {
  max-height: 280px; overflow-y: auto;
  border: 1px solid #e2e8f0;
  background: #fafafa;
}
._eli3_bd_tpl_row {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 10px;
  border-bottom: 1px solid #e2e8f0;
}
._eli3_bd_tpl_row:last-child { border-bottom: none; }
._eli3_bd_tpl_row_core { background: #eff6ff; }
._eli3_bd_tpl_row_prior { background: #fff; }
._eli3_bd_tpl_row_main { flex: 1; min-width: 0; }
._eli3_bd_tpl_row_name {
  font: 700 12px/1.2 'Georgia', serif;
  color: #0f172a;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
._eli3_bd_tpl_row_meta {
  font: 500 10px/1.3 'Inter', sans-serif;
  color: #64748b; margin-top: 2px;
}
._eli3_bd_tpl_row_load,
._eli3_bd_tpl_row_del {
  flex: 0 0 auto;
  background: #fff; border: 1px solid #cbd5e1;
  font: 600 12px/1 'Inter', sans-serif;
  padding: 6px 8px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_bd_tpl_row_load:hover {
  background: #ecfdf5; border-color: #047857;
}
._eli3_bd_tpl_row_del:hover {
  background: #fee2e2; border-color: #dc2626;
}
._eli3_bd_tpl_empty {
  padding: 24px; text-align: center;
  font: 500 12px/1.4 'Inter', sans-serif;
  color: #94a3b8;
}
._eli3_bd_tpl_bulk {
  display: flex; gap: 8px; margin-top: 10px;
}
._eli3_bd_tpl_bulk_btn {
  flex: 1;
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #475569;
  padding: 9px 8px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_bd_tpl_bulk_btn:hover {
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border-color: #1565c0; color: #1565c0;
}

/* =====================================================================
   Save panel (renderSavePanel)
   ===================================================================== */
/* Header inherits the standard dark navy `_eli3_bd_bar` — no override. */
._eli3_bd_save_settings {
  background: rgba(255,255,255,0.10);
  border: 1px solid rgba(255,255,255,0.20);
  color: #f2d866;
  font-size: 14px; line-height: 1;
  padding: 6px 10px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_bd_save_settings:hover {
  background: rgba(201,162,39,0.25);
  border-color: rgba(201,162,39,0.6);
  transform: translateY(-1px);
}
._eli3_bd_save_scanloader {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 10px;
  padding: 10px 14px;
  background: #eff6ff;
  border-bottom: 1px solid #bfdbfe;
  font: 600 11px/1.4 'Inter', sans-serif;
  color: #1e40af;
}
._eli3_bd_save_spinner {
  width: 14px; height: 14px;
  border: 2px solid #93c5fd;
  border-top-color: #1565c0;
  border-radius: 50%;
  animation: _eli3_bd_save_spin 0.8s linear infinite;
}
@keyframes _eli3_bd_save_spin { to { transform: rotate(360deg); } }
._eli3_bd_save_form {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 14px;
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_bd_save_label {
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #0f172a; margin-top: 6px;
}
._eli3_bd_save_input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid #cbd5e1;
  background: #fff;
  font: 500 13px/1.3 'Inter', sans-serif;
  color: #0f172a;
  box-sizing: border-box;
  outline: none;
}
._eli3_bd_save_input:focus {
  border-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21,101,192,0.18);
}
._eli3_bd_save_hidden { display: none !important; }

/* FROM v2 IS_EXECUTION_MODE toggle — amber accent so it stands out. */
._eli3_bd_save_execmode {
  display: flex; align-items: flex-start; gap: 10px;
  margin-top: 12px;
  padding: 10px 12px;
  background: linear-gradient(180deg, #fffbeb 0%, #fef3c7 100%);
  border: 1px solid #fde68a;
  border-left: 4px solid #f59e0b;
  cursor: pointer;
  user-select: none;
}
._eli3_bd_save_execmode input[type="checkbox"] {
  margin: 2px 0 0 0;
  flex: 0 0 auto;
  accent-color: #d97706;
  width: 16px; height: 16px;
}
._eli3_bd_save_execmode_main {
  display: flex; flex-direction: column; gap: 2px;
}
._eli3_bd_save_execmode_label {
  font: 800 11px/1.2 'Inter', sans-serif;
  color: #92400e;
  letter-spacing: 0.3px;
}
._eli3_bd_save_execmode_hint {
  font: 500 10px/1.3 'Inter', sans-serif;
  color: #b45309;
  font-style: italic;
}
._eli3_bd_save_preview {
  margin-top: 12px;
  padding: 10px 12px;
  background: #f5f5f5;
  border: 1px solid #e2e8f0;
  display: flex; flex-direction: column; gap: 4px;
}
._eli3_bd_save_preview_label {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #64748b;
}
._eli3_bd_save_preview_value {
  font: 600 12px/1.4 monospace;
  color: #0f172a; word-break: break-all;
}
/* Skip + Save row — equal-width buttons, save on the right (primary). */
._eli3_bd_save_actions {
  display: flex;
  gap: 8px;
  margin-top: 14px;
}
._eli3_bd_save_skip {
  flex: 1;
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #475569;
  padding: 10px 14px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_bd_save_skip:hover {
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  color: #0f172a;
  border-color: #94a3b8;
}
._eli3_bd_save_btn {
  flex: 1.6;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  font: 700 12px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  padding: 10px 14px;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: 0 2px 6px rgba(21, 101, 192, 0.25);
}
._eli3_bd_save_btn:hover:not(:disabled) {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(21, 101, 192, 0.35);
}
._eli3_bd_save_btn:disabled { opacity: 0.6; cursor: progress; }
._eli3_bd_save_btn_icon { font-size: 14px; line-height: 1; }
._eli3_bd_save_btn_label { white-space: nowrap; }

/* ─── Filename builder + copy-paste block (2026-05-16 rework) ─── */
/* Big monospace filename target — click-to-select, prominent copy
   button below, ack toast slot below the button. Replaces the small
   inline preview pill. */
._eli3_bd_fn_block {
  margin: 14px 0 8px;
  padding: 14px;
  background: linear-gradient(180deg, #f8fafc 0%, #eff6ff 100%);
  border: 1px solid #93c5fd;
  border-left: 4px solid #1565c0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
._eli3_bd_fn_label {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #1e3a8a;
}
._eli3_bd_fn_value {
  font: 600 15px/1.4 'Consolas', 'Monaco', monospace;
  color: #0f172a;
  background: #fff;
  padding: 12px 14px;
  border: 1px solid #cbd5e1;
  word-break: break-all;
  cursor: pointer;
  user-select: all;
  transition: border-color 0.12s, background 0.12s;
}
._eli3_bd_fn_value:hover {
  border-color: #1565c0;
  background: #fffbeb;
}
._eli3_bd_fn_copy {
  align-self: flex-start;
  padding: 10px 18px;
  font: 700 12px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: 0 2px 6px rgba(21, 101, 192, 0.25);
}
._eli3_bd_fn_copy:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(21, 101, 192, 0.35);
}
._eli3_bd_fn_copy_ack {
  padding: 8px 10px;
  background: #d1fae5;
  border: 1px solid #6ee7b7;
  border-left: 3px solid #10b981;
  font-size: 11px;
  color: #065f46;
  line-height: 1.4;
}
._eli3_bd_fn_copy_ack kbd {
  display: inline-block;
  padding: 1px 6px;
  font: 700 10px/1.2 'Consolas', monospace;
  background: #fff;
  border: 1px solid #6ee7b7;
  border-radius: 3px;
  color: #065f46;
  margin: 0 1px;
}

/* Step-by-step instructions block */
._eli3_bd_fn_steps {
  margin: 8px 0 4px;
  padding: 12px 14px;
  background: #fffbeb;
  border: 1px solid #fcd34d;
  border-left: 3px solid #f59e0b;
}
._eli3_bd_fn_steps_head {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #92400e;
  margin-bottom: 6px;
}
._eli3_bd_fn_steps_list {
  margin: 0;
  padding-left: 20px;
  font-size: 11px;
  line-height: 1.7;
  color: #0f172a;
}
._eli3_bd_fn_steps_list strong { color: #1e3a8a; }
._eli3_bd_fn_steps_list kbd {
  display: inline-block;
  padding: 1px 6px;
  font: 700 10px/1.2 'Consolas', monospace;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: 3px;
  color: #0f172a;
  margin: 0 1px;
}
._eli3_bd_fn_why {
  margin-top: 8px;
  padding-top: 6px;
  font-size: 10px;
  color: #92400e;
  font-style: italic;
  border-top: 1px dashed #fcd34d;
}

/* Dark mode */
